/* ============================================================================
   QCM STYLE EXAMEN — banque de questions par section
   q   = énoncé (scénario ou question directe)
   o   = options
   c   = index de la bonne réponse
   e   = explication (pourquoi la bonne est bonne, pourquoi les autres non)
   obj = objectif CompTIA rattaché
   ========================================================================== */
(function (App) {
  'use strict';

  App.QUESTIONS = {

  /* ---------------------------- 1. Introduction ---------------------------- */
  1: [
    { q: "Vous préparez votre planning d'examen. Combien de questions maximum comporte le SY0-701 et en combien de temps ?", o: ["90 questions en 90 minutes", "100 questions en 120 minutes", "75 questions en 60 minutes", "80 questions en 105 minutes"], c: 0,
      e: "Le SY0-701 comporte un **maximum de 90 questions** à traiter en **90 minutes**, soit environ une minute par question. Les autres formats correspondent à d'autres certifications et ne s'appliquent pas ici.", obj: "Format d'examen" },
    { q: "Quel score faut-il atteindre pour réussir le SY0-701 ?", o: ["700 sur 1000", "750 sur 900", "800 sur 900", "70 % de bonnes réponses"], c: 1,
      e: "Le score de passage est de **750 sur une échelle de 100 à 900**. Attention : ce n'est pas un pourcentage de bonnes réponses, car les questions n'ont pas toutes le même poids.", obj: "Format d'examen" },
    { q: "Vous démarrez l'examen et les trois premières questions sont des PBQ complexes. Quelle est la meilleure stratégie ?", o: ["Les résoudre entièrement avant de continuer, car elles valent plus de points", "Les marquer et y revenir après avoir traité tous les QCM", "Les laisser vides définitivement pour gagner du temps", "Deviner rapidement et ne jamais y revenir"], c: 1,
      e: "Les PBQ sont **chronophages** et apparaissent en début d'examen. La stratégie recommandée est de les **marquer (flag)** et d'y revenir **à la fin**, une fois tous les QCM sécurisés. Les laisser vides serait une erreur : elles accordent souvent des **points partiels**.", obj: "Stratégie d'examen" },
    { q: "Quel domaine représente la plus grande proportion de l'examen ?", o: ["2.0 Threats, Vulnerabilities and Mitigations (22 %)", "3.0 Security Architecture (18 %)", "4.0 Security Operations (28 %)", "5.0 Security Program Management and Oversight (20 %)"], c: 2,
      e: "Le domaine **4.0 Security Operations pèse 28 %**, soit le plus lourd. Il est suivi de 2.0 (22 %), 5.0 (20 %), 3.0 (18 %) et enfin 1.0 (12 %). C'est donc le domaine sur lequel investir le plus de temps de révision.", obj: "Format d'examen" },
    { q: "Vous hésitez entre deux réponses et le temps presse. Que faire ?", o: ["Laisser la question vide pour éviter une pénalité", "Choisir une réponse, car il n'y a pas de point négatif", "Cocher les deux réponses possibles", "Signaler la question comme ambiguë"], c: 1,
      e: "L'examen **ne comporte aucun point négatif**. Laisser une question vide garantit zéro point, alors qu'une réponse même incertaine offre une chance de la marquer. Il faut donc **toujours répondre**.", obj: "Stratégie d'examen" },
    { q: "Quelle expérience professionnelle CompTIA recommande-t-elle avant de passer le Security+ ?", o: ["Aucune expérience requise", "5 ans en développement logiciel", "2 ans en administration IT orientée sécurité", "10 ans en gestion de projet"], c: 2,
      e: "CompTIA recommande **au minimum 2 ans d'expérience en administration IT avec une orientation sécurité**, ainsi qu'une expérience pratique de la sécurité technique. Ce n'est toutefois pas un prérequis bloquant pour s'inscrire.", obj: "Format d'examen" }
  ],

  /* ---------------------- 2. Fundamentals of Security ---------------------- */
  2: [
    { q: "Une entreprise chiffre l'intégralité des disques de ses ordinateurs portables. Quel principe de la triade CIA est principalement renforcé ?", o: ["Integrity", "Availability", "Confidentiality", "Non-repudiation"], c: 2,
      e: "Le chiffrement empêche toute personne non autorisée de **lire** les données : il sert la **confidentialité**. L'intégrité s'obtient par le **hachage**, la disponibilité par la **redondance**, et la non-répudiation par la **signature numérique**.", obj: "1.2" },
    { q: "Un administrateur installe un panneau « Zone sous vidéosurveillance » à l'entrée du bâtiment. Quel TYPE de contrôle met-il en place ?", o: ["Preventive", "Deterrent", "Detective", "Corrective"], c: 1,
      e: "Un panneau **décourage** sans empêcher physiquement l'intrusion : c'est un contrôle **deterrent**. Un contrôle **preventive** bloquerait réellement (une serrure), un **detective** constaterait après coup (la caméra elle-même), un **corrective** réparerait après l'incident.", obj: "1.1" },
    { q: "Une politique de sécurité écrite imposant la rotation des mots de passe relève de quelle CATÉGORIE de contrôle ?", o: ["Technical", "Physical", "Operational", "Managerial"], c: 3,
      e: "Une **politique écrite** est un instrument de gestion : catégorie **Managerial**. Si le système **impose techniquement** la rotation, c'est alors un contrôle **Technical**. Attention à bien distinguer le document (managerial) de son application technique.", obj: "1.1" },
    { q: "Un système ICS critique ne peut pas être patché sans arrêter la production. L'équipe le place derrière un pare-feu dédié et le segmente. Quel type de contrôle est mis en œuvre ?", o: ["Compensating", "Directive", "Deterrent", "Detective"], c: 0,
      e: "Quand le contrôle prévu (le correctif) est **impossible à appliquer**, on met en place un contrôle **alternatif** qui atteint un objectif de sécurité comparable : c'est la définition exacte d'un contrôle **compensating**.", obj: "1.1" },
    { q: "Dans une architecture Zero Trust, quel composant PREND la décision d'autoriser ou de refuser un accès ?", o: ["Le Policy Enforcement Point", "Le Policy Engine", "Le Policy Administrator", "L'Implicit Trust Zone"], c: 1,
      e: "Le **Policy Engine DÉCIDE**, le **Policy Administrator COMMUNIQUE** cette décision, et le **Policy Enforcement Point APPLIQUE** concrètement l'autorisation ou le blocage. L'implicit trust zone est une notion du Data Plane, pas un décideur.", obj: "1.2" },
    { q: "Un client nie avoir passé une commande en ligne, mais celle-ci était signée numériquement avec son certificat. Quel principe permet de réfuter sa contestation ?", o: ["Confidentiality", "Availability", "Non-repudiation", "Authentication"], c: 2,
      e: "La **non-répudiation** empêche un acteur de nier une action qu'il a réalisée. Elle repose sur la **signature numérique**, car seule la clé privée du signataire a pu produire cette signature. L'authentification prouve l'identité au moment de la connexion, mais ne fournit pas cette preuve opposable.", obj: "1.2" },
    { q: "Une organisation compare sa posture de sécurité actuelle avec les exigences de la norme ISO 27001 qu'elle vise. Comment nomme-t-on cette démarche ?", o: ["Business impact analysis", "Gap analysis", "Penetration test", "Risk register"], c: 1,
      e: "Une **gap analysis** mesure l'**écart entre la situation actuelle et la cible** souhaitée. La BIA identifie les fonctions critiques et les RTO/RPO, le pentest exploite des failles, et le risk register recense les risques identifiés.", obj: "1.2" },
    { q: "Quel élément de l'AAA répond à la question « qu'a fait cet utilisateur sur le système ? »", o: ["Authentication", "Authorization", "Accounting", "Attestation"], c: 2,
      e: "L'**Accounting** correspond à la **journalisation des actions**. L'Authentication vérifie l'identité (qui êtes-vous ?), l'Authorization détermine les droits (que pouvez-vous faire ?). L'attestation est une validation formelle des accès, elle ne fait pas partie de l'AAA.", obj: "1.2" },
    { q: "Une vulnérabilité critique existe sur un serveur, mais celui-ci est totalement déconnecté et inaccessible. Que peut-on en conclure ?", o: ["Le risque reste identique car la vulnérabilité existe", "Le risque est très faible car la menace ne peut pas l'atteindre", "La vulnérabilité devient une menace", "Le risque est maximal"], c: 1,
      e: "Le **risque résulte de la combinaison d'une menace ET d'une vulnérabilité exploitable**. Si aucune menace ne peut atteindre le système, le risque devient **très faible**, même si la vulnérabilité technique subsiste.", obj: "1.2" },
    { q: "Un plan de reprise d'activité (DRP) mis en œuvre après un sinistre correspond à quel type de contrôle ?", o: ["Preventive", "Detective", "Corrective", "Deterrent"], c: 2,
      e: "Un contrôle **corrective** intervient **après l'incident pour rétablir** la situation normale. Le DRP en est l'exemple type. En termes de catégorie, il s'agit d'un contrôle **Managerial** puisque c'est un document de gestion.", obj: "1.1" },
    { q: "Une entreprise déploie une solution qui vérifie l'identité et la posture de sécurité de chaque appareil à CHAQUE demande d'accès, y compris depuis le réseau interne. Quel modèle applique-t-elle ?", o: ["Défense en profondeur classique", "Zero Trust", "Sécurité périmétrique", "Air gap"], c: 1,
      e: "Le **Zero Trust** repose sur le principe « **never trust, always verify** » : aucune confiance implicite n'est accordée, **même à l'intérieur du périmètre**. La sécurité périmétrique, à l'inverse, fait confiance à ce qui est déjà à l'intérieur.", obj: "1.2" },
    { q: "Quel ensemble décrit correctement les 4 CATÉGORIES de contrôles de sécurité ?", o: ["Preventive, Detective, Corrective, Deterrent", "Technical, Managerial, Operational, Physical", "Confidentiality, Integrity, Availability, Non-repudiation", "Mandatory, Discretionary, Role-based, Attribute-based"], c: 1,
      e: "Les **4 catégories** sont **Technical, Managerial, Operational et Physical** : elles décrivent **qui ou quoi met en œuvre** le contrôle. La première proposition liste des **types** (l'effet recherché), la troisième des principes, la quatrième des modèles de contrôle d'accès.", obj: "1.1" }
  ],

  /* ---------------------------- 3. Threat Actors --------------------------- */
  3: [
    { q: "Un groupe très bien financé mène une campagne d'intrusion silencieuse pendant 18 mois pour dérober des plans industriels. Quel acteur de menace correspond le mieux ?", o: ["Unskilled attacker", "Hacktivist", "Nation-state actor", "Shadow IT"], c: 2,
      e: "La combinaison **ressources très importantes + persistance sur une longue durée + espionnage industriel** caractérise un **acteur étatique**, généralement associé à une **APT**. Un unskilled attacker n'a ni les moyens ni la patience, un hacktivist agit publiquement pour une cause.", obj: "2.1" },
    { q: "Un développeur installe un service cloud de partage de fichiers sans en informer la DSI pour faciliter son travail. Comment qualifie-t-on cette situation ?", o: ["Insider threat malveillant", "Shadow IT", "Hacktivisme", "Supply chain attack"], c: 1,
      e: "Le **Shadow IT** désigne l'usage de matériel, logiciel ou service **sans l'accord de la DSI**. L'intention n'est **pas malveillante** ici, ce qui l'écarte de l'insider threat malveillant, mais le risque est réel car l'actif échappe à toute gestion et supervision.", obj: "2.1" },
    { q: "Quel acteur de menace présente le risque le plus élevé de contourner les défenses périmétriques et pourquoi ?", o: ["L'attaquant externe non qualifié, car il est nombreux", "L'insider threat, car il dispose déjà d'un accès légitime", "Le hacktivist, car il est très motivé", "Le crime organisé, car il est bien financé"], c: 1,
      e: "L'**insider threat** possède **déjà un accès légitime** et connaît l'organisation : les défenses périmétriques, conçues pour arrêter l'extérieur, ne le concernent pas. C'est ce qui rend cette menace si difficile à détecter.", obj: "2.1" },
    { q: "Un adolescent utilise un outil de DDoS téléchargé sur un forum pour faire tomber le site de son école. Quel acteur et quelle motivation ?", o: ["Nation-state, espionnage", "Unskilled attacker, disruption/chaos", "Organized crime, gain financier", "Insider threat, revenge"], c: 1,
      e: "L'usage d'un **outil tout fait sans compétence technique propre** caractérise l'**unskilled attacker** (script kiddie). La motivation est ici la **perturbation et le chaos**, non le gain financier ni l'espionnage.", obj: "2.1" },
    { q: "Quels sont les trois attributs utilisés pour comparer les acteurs de menace ?", o: ["Motivation, cible, outil utilisé", "Interne/externe, ressources/financement, niveau de sophistication", "Vitesse, discrétion, persistance", "Localisation, langue, fuseau horaire"], c: 1,
      e: "CompTIA retient trois attributs : **interne ou externe**, **ressources et financement**, et **niveau de sophistication et de capacité**. La motivation est une catégorie distincte, ce n'est pas un attribut au sens de l'objectif 2.1.", obj: "2.1" },
    { q: "Un attaquant compromet un éditeur de logiciel pour insérer une porte dérobée dans une mise à jour distribuée à des milliers de clients. Quel vecteur est utilisé ?", o: ["Phishing", "Supply chain", "Removable device", "Open service port"], c: 1,
      e: "Compromettre un **fournisseur (éditeur, MSP, prestataire)** pour atteindre indirectement ses clients est une attaque de la **chaîne d'approvisionnement (supply chain)**. C'est le schéma de l'affaire SolarWinds.", obj: "2.2" },
    { q: "Une organisation découvre que ses équipements réseau utilisent encore les identifiants d'usine. Pourquoi est-ce si critique ?", o: ["Ils ralentissent les performances", "Ils sont publiquement documentés dans les manuels constructeurs", "Ils empêchent les mises à jour", "Ils sont incompatibles avec le chiffrement"], c: 1,
      e: "Les identifiants par défaut sont **publiés dans la documentation constructeur** et compilés dans des bases accessibles à tous. Un attaquant les teste **en premier**, sans aucun effort ni compétence particulière.", obj: "2.2" },
    { q: "Quelle est la différence entre une attack surface et un threat vector ?", o: ["Ce sont deux synonymes", "L'attack surface est l'ensemble des points d'entrée possibles, le threat vector est le chemin réellement emprunté", "Le threat vector est plus large que l'attack surface", "L'attack surface concerne uniquement le réseau"], c: 1,
      e: "L'**attack surface** regroupe **tous les points d'entrée potentiels** ; le **threat vector** est le **chemin précis effectivement utilisé** par l'attaquant. On cherche à **réduire la surface** et à **bloquer les vecteurs**.", obj: "2.2" },
    { q: "Un groupe défigure le site d'une entreprise pétrolière pour dénoncer son impact environnemental. Quelle motivation principale ?", o: ["Financial gain", "Philosophical/political beliefs", "Espionage", "Blackmail"], c: 1,
      e: "Une action militante visant à faire passer un message relève de convictions **philosophiques ou politiques** : c'est la signature du **hacktivist**. Il n'y a ici ni demande de rançon (blackmail) ni vol de données à des fins lucratives.", obj: "2.1" },
    { q: "Pourquoi un système en fin de vie (end-of-life) constitue-t-il un vecteur de menace durable ?", o: ["Il consomme trop de ressources", "Il ne reçoit plus de correctifs, donc chaque nouvelle faille y reste exploitable", "Il est incompatible avec les antivirus", "Il ralentit le réseau"], c: 1,
      e: "Un système non supporté **ne reçoit plus de correctifs de sécurité**. Chaque vulnérabilité découverte après la fin de support y demeure **exploitable indéfiniment**. La parade consiste à le **segmenter** et à appliquer des contrôles compensatoires.", obj: "2.2" },
    { q: "Quelle motivation caractérise principalement le crime organisé en cybersécurité ?", o: ["Les convictions politiques", "Le gain financier", "La guerre", "L'éthique"], c: 1,
      e: "Le **crime organisé** poursuit avant tout le **gain financier**. Très bien financé et sophistiqué, il est à l'origine de l'essentiel des campagnes de **ransomware** et de fraude à grande échelle.", obj: "2.1" }
  ],

  /* --------------------------- 4. Physical Security ------------------------ */
  4: [
    { q: "Un site doit empêcher qu'un véhicule ne percute l'entrée du bâtiment tout en laissant circuler les piétons. Quelle mesure choisir ?", o: ["Une clôture grillagée", "Des bollards", "Un access control vestibule", "Un tourniquet"], c: 1,
      e: "Les **bollards** (bornes anti-bélier) sont conçus exactement pour cela : **arrêter les véhicules** tout en laissant **passer les piétons**. Une clôture bloquerait aussi les piétons et un vestibule contrôle l'accès des personnes, pas des véhicules.", obj: "1.2" },
    { q: "Un employé badge à l'entrée et une personne inconnue le suit dans le sas sans badger, à son insu. Comment nomme-t-on cela et quelle est la parade ?", o: ["Piggybacking, contré par un garde", "Tailgating, contré par un access control vestibule", "Shoulder surfing, contré par un écran de confidentialité", "Impersonation, contrée par la biométrie"], c: 1,
      e: "Suivre quelqu'un **à son insu** est du **tailgating** (avec son consentement, ce serait du **piggybacking**). L'**access control vestibule** (mantrap) est la contre-mesure de référence : une seule personne peut franchir le sas à la fois.", obj: "1.2" },
    { q: "Une entreprise déploie des honeyfiles sur ses serveurs de fichiers. Quel est l'objectif ?", o: ["Bloquer l'accès aux vrais fichiers", "Détecter un accès non autorisé et alerter", "Chiffrer les données sensibles", "Sauvegarder les données critiques"], c: 1,
      e: "Un **honeyfile** est un **fichier appât** : aucun utilisateur légitime n'a de raison d'y accéder, donc **tout accès déclenche une alerte fiable**. Les technologies de tromperie servent à **détecter et étudier**, pas à bloquer.", obj: "1.2" },
    { q: "Quel capteur détecte une intrusion en mesurant la chaleur corporelle ?", o: ["Pressure", "Microwave", "Infrared", "Ultrasonic"], c: 2,
      e: "Le capteur **infrarouge** détecte le **rayonnement thermique**. Le **pressure** détecte le poids, le **microwave** le mouvement par ondes radio, l'**ultrasonic** le mouvement par ondes sonores.", obj: "1.2" },
    { q: "Une caméra de vidéosurveillance enregistre en continu l'entrée d'un entrepôt. En termes de type de contrôle, elle est avant tout :", o: ["Preventive", "Detective", "Corrective", "Compensating"], c: 1,
      e: "Une caméra **constate et enregistre** : c'est un contrôle **detective**. Elle n'empêche pas physiquement l'intrusion. Sa présence visible produit toutefois un effet **deterrent** secondaire, mais sa fonction première reste la détection.", obj: "1.1" },
    { q: "Un attaquant clone le badge RFID d'un employé en s'approchant de lui dans les transports. Quelle contre-mesure est la plus efficace ?", o: ["Augmenter la hauteur de la clôture", "Utiliser des badges chiffrés couplés à un code PIN", "Installer davantage de caméras", "Renforcer l'éclairage du parking"], c: 1,
      e: "Contre le clonage, il faut d'une part des **badges chiffrés** (bien plus difficiles à copier), d'autre part ajouter un **second facteur** comme un code PIN ou la biométrie. Caméras et éclairage n'empêchent pas le clonage, qui se produit hors du site.", obj: "1.2" },
    { q: "Quel dispositif de sécurité physique est le seul capable d'exercer un jugement discrétionnaire face à une situation imprévue ?", o: ["Le tourniquet", "Le garde de sécurité", "Le capteur de mouvement", "Le lecteur de badge"], c: 1,
      e: "Seul le **garde de sécurité** peut **analyser une situation inédite et adapter sa réponse**. Tous les dispositifs automatiques appliquent des règles fixes et ne savent pas traiter l'imprévu.", obj: "1.2" },
    { q: "Quelle différence y a-t-il entre un honeypot et un honeynet ?", o: ["Le honeypot est logiciel, le honeynet matériel", "Le honeypot est un système leurre, le honeynet est un réseau entier de leurres", "Le honeynet est un fichier appât", "Il n'y a aucune différence"], c: 1,
      e: "Un **honeypot** est **un système** leurre isolé ; un **honeynet** est un **réseau complet** de systèmes leurres, qui permet d'observer les déplacements latéraux de l'attaquant. Le fichier appât est un **honeyfile**.", obj: "1.2" },
    { q: "Un attaquant coupe l'alimentation électrique d'un local technique pour désactiver les systèmes de sécurité. De quel type d'attaque s'agit-il ?", o: ["Brute force", "Attaque environnementale", "RFID cloning", "Tailgating"], c: 1,
      e: "S'attaquer aux **conditions d'environnement** (électricité, climatisation, eau) plutôt qu'au système lui-même constitue une **attaque environnementale**. La brute force physique consisterait à forcer une porte ou un cadenas.", obj: "2.4" }
  ],

  /* -------------------------- 5. Social Engineering ------------------------ */
  5: [
    { q: "Un directeur financier reçoit un SMS prétendant venir de sa banque et l'invitant à cliquer sur un lien urgent. Quelle attaque est-ce ?", o: ["Phishing", "Vishing", "Smishing", "Whaling"], c: 2,
      e: "Une attaque menée **par SMS** est un **smishing** (SMS + phishing). Le phishing passe par email, le vishing par appel vocal. Le whaling désigne le ciblage d'un dirigeant, mais l'examen attend ici la qualification par le **support utilisé**.", obj: "2.2" },
    { q: "Un comptable reçoit un email provenant de la véritable adresse du PDG, demandant un virement urgent vers un nouveau fournisseur. L'enquête montre que la boîte mail du PDG a été compromise. Quelle attaque ?", o: ["Spear phishing", "Business Email Compromise", "Typosquatting", "Watering hole"], c: 1,
      e: "Quand une **boîte mail interne légitime est réellement compromise** et utilisée pour émettre des ordres frauduleux, il s'agit d'un **Business Email Compromise (BEC)**. C'est redoutable car l'expéditeur est **authentique** : ni SPF, ni DKIM, ni DMARC ne détecteront l'anomalie.", obj: "2.2" },
    { q: "Un attaquant appelle le support en se présentant comme un technicien réseau intervenant en urgence sur une panne, afin d'obtenir un accès. Quelle technique emploie-t-il ?", o: ["Pretexting", "Watering hole", "Typosquatting", "Tailgating"], c: 0,
      e: "**Inventer un scénario crédible** pour justifier sa demande est du **pretexting**. Il s'y ajoute ici de l'**impersonation** (se faire passer pour un technicien), mais la technique centrale décrite reste le prétexte construit.", obj: "2.2" },
    { q: "Des employés d'une entreprise sont infectés après avoir consulté un site d'actualité sectorielle qu'ils visitent quotidiennement et qui a été compromis. Quelle attaque ?", o: ["Phishing", "Watering hole", "Evil twin", "Pharming"], c: 1,
      e: "Compromettre un **site tiers légitime que la cible fréquente habituellement** est une attaque de type **watering hole** (point d'eau). L'attaquant n'a pas besoin de contacter directement ses victimes : il les attend là où elles vont.", obj: "2.2" },
    { q: "Un employé partage de bonne foi une information fausse lue sur les réseaux sociaux, sans intention de nuire. Comment qualifier cela ?", o: ["Disinformation", "Misinformation", "Pretexting", "Impersonation"], c: 1,
      e: "La **misinformation** est une information fausse diffusée **sans intention de nuire**. La **disinformation** est fausse et diffusée **délibérément** pour tromper. L'intention est le seul critère de distinction.", obj: "2.2" },
    { q: "Une entreprise veut réduire durablement son exposition à l'ingénierie sociale. Quelle mesure est la PLUS efficace ?", o: ["Installer un pare-feu de nouvelle génération", "Mettre en place une formation récurrente et des campagnes de phishing simulé", "Chiffrer tous les disques durs", "Déployer un IPS"], c: 1,
      e: "L'ingénierie sociale cible **l'humain**, pas la technique : aucun pare-feu ni IPS ne l'arrête. Seules la **formation récurrente** et les **campagnes de phishing simulé** améliorent durablement la vigilance des utilisateurs.", obj: "5.6" },
    { q: "Un attaquant enregistre le domaine « micosoft-support.com » pour piéger les utilisateurs distraits. Quelle technique ?", o: ["Pharming", "Typosquatting", "Domain hijacking", "DNS poisoning"], c: 1,
      e: "Enregistrer un domaine ressemblant fortement au domaine légitime, avec une **faute de frappe ou une variation**, est du **typosquatting**. Le domain hijacking consiste à voler le vrai domaine, le DNS poisoning à corrompre la résolution.", obj: "2.2" },
    { q: "Quel levier psychologique un attaquant exploite-t-il en écrivant « Votre compte sera clôturé dans 2 heures si vous n'agissez pas » ?", o: ["Authority", "Urgency", "Social proof", "Likability"], c: 1,
      e: "L'**urgence** est le levier le plus employé car elle **empêche la victime de prendre le temps de vérifier**. Sous pression temporelle, le raisonnement critique est court-circuité au profit de la réaction immédiate.", obj: "2.2" },
    { q: "Un utilisateur reçoit un email suspect. Quelle est la conduite à tenir ?", o: ["Le transférer à ses collègues pour les avertir", "Y répondre pour vérifier l'identité de l'expéditeur", "Le signaler via le canal dédié sans cliquer ni transférer", "Le supprimer immédiatement sans rien dire"], c: 2,
      e: "Il faut **signaler** le message au SOC via le bouton dédié, **sans cliquer, sans répondre et sans le transférer**. Le transfert propage la menace, la réponse confirme que l'adresse est active, et la suppression silencieuse prive l'équipe sécurité d'une information précieuse.", obj: "5.6" },
    { q: "Quelle différence entre spear phishing et whaling ?", o: ["Le whaling utilise le SMS, le spear phishing l'email", "Le spear phishing cible un groupe ou une personne précise, le whaling cible spécifiquement un dirigeant", "Le whaling est automatisé, le spear phishing manuel", "Il n'y a aucune différence"], c: 1,
      e: "Le **spear phishing** vise une **cible précise** (une personne ou un petit groupe) avec un message personnalisé ; le **whaling** est un spear phishing dont la cible est un **dirigeant de haut niveau (C-level)**, dont la compromission a un impact majeur.", obj: "2.2" }
  ],

  /* -------------------------------- 6. Malware ----------------------------- */
  6: [
    { q: "Un administrateur constate une saturation soudaine de la bande passante et une explosion des connexions entre machines internes, sans qu'aucun utilisateur n'ait ouvert de pièce jointe. Quel malware suspecter ?", o: ["Un virus", "Un ver (worm)", "Un keylogger", "Une bombe logique"], c: 1,
      e: "La propagation **autonome, sans interaction utilisateur**, accompagnée d'une **saturation réseau**, est la signature du **ver**. Le virus, lui, exige un fichier hôte et une action de l'utilisateur pour se propager.", obj: "2.4" },
    { q: "Après une compromission, les analystes découvrent que l'antivirus, le gestionnaire de tâches et les journaux ne montrent aucune trace du processus malveillant, qui opère pourtant en mode noyau. De quel malware s'agit-il ?", o: ["Un adware", "Un rootkit", "Un bloatware", "Un cheval de Troie classique"], c: 1,
      e: "Un **rootkit** obtient des **privilèges élevés** et **se dissimule**, souvent en **mode noyau**, en mentant au système d'exploitation lui-même. Sa détection exige généralement un **démarrage sur un support externe** ou une analyse hors ligne.", obj: "2.4" },
    { q: "Quelle est la défense la PLUS efficace contre un ransomware ?", o: ["Payer rapidement la rançon pour récupérer les données", "Disposer de sauvegardes hors ligne, régulières et testées", "Installer un second antivirus", "Désactiver les macros uniquement"], c: 1,
      e: "Seules des **sauvegardes hors ligne (ou immuables), régulières et surtout TESTÉES** permettent de restaurer sans céder au chantage. Payer ne garantit **ni la clé de déchiffrement, ni la non-publication** des données, et finance l'écosystème criminel.", obj: "2.5" },
    { q: "Un code malveillant dormant s'active automatiquement le jour où le compte d'un ancien administrateur est supprimé de l'annuaire. Quel type de malware ?", o: ["Un ver", "Une bombe logique", "Un rootkit", "Un spyware"], c: 1,
      e: "Une **bombe logique** est un code déclenché par une **condition précise** : une date, un événement ou, comme ici, la disparition d'un compte. C'est un scénario classique de sabotage par un employé sur le départ.", obj: "2.4" },
    { q: "Un logiciel préinstallé par le fabricant sur les nouveaux portables n'est jamais utilisé et n'est plus mis à jour. Comment le qualifier ?", o: ["Spyware", "Bloatware", "Rootkit", "Trojan"], c: 1,
      e: "Le **bloatware** est un logiciel **préinstallé et inutile**. Il n'est **pas malveillant en soi**, mais comme il n'est ni utilisé ni maintenu, il **augmente inutilement la surface d'attaque**. La bonne pratique est de le désinstaller.", obj: "2.4" },
    { q: "Des machines de l'entreprise établissent périodiquement des connexions vers une adresse externe inconnue et exécutent des commandes reçues. Quelle infrastructure est en jeu ?", o: ["Un serveur DNS interne", "Un serveur command and control (C2)", "Un proxy inverse", "Un serveur RADIUS"], c: 1,
      e: "Un serveur **C2 (command and control)** pilote les machines compromises (**zombies**) et récupère les données exfiltrées. L'ensemble forme un **botnet**. Couper la communication avec le C2 neutralise le réseau de zombies.", obj: "2.4" },
    { q: "Un malware s'exécute uniquement en mémoire en détournant PowerShell, sans jamais écrire de fichier sur le disque. Quelle catégorie ?", o: ["Fileless malware", "Virus de secteur d'amorçage", "Bloatware", "Adware"], c: 0,
      e: "Un **fileless malware** vit **exclusivement en mémoire** et détourne des outils légitimes du système (PowerShell, WMI). Il échappe ainsi aux antivirus qui analysent les fichiers sur disque : seule une détection **comportementale** le repère.", obj: "2.4" },
    { q: "Un utilisateur signale que sa machine est très lente et que le ventilateur tourne en permanence. Le CPU est à 100 % à cause d'un processus inconnu. Quelle hypothèse privilégier ?", o: ["Un keylogger", "Du cryptojacking", "Un spyware", "Une bombe logique"], c: 1,
      e: "Une **consommation CPU/GPU maximale et permanente** sans activité utilisateur correspondante est la signature du **cryptojacking** (minage clandestin de cryptomonnaie). Un keylogger ou un spyware sont au contraire conçus pour être **discrets**.", obj: "2.4" },
    { q: "Quelle différence essentielle sépare un virus d'un cheval de Troie ?", o: ["Le virus se propage seul, le trojan non", "Le virus a besoin d'un fichier hôte pour se répliquer, le trojan se déguise en logiciel légitime", "Le trojan chiffre les fichiers, le virus les supprime", "Le virus est toujours en mémoire"], c: 1,
      e: "Le **virus** infecte un **fichier hôte** et s'y réplique. Le **cheval de Troie** ne se réplique pas : il **se fait passer pour un logiciel légitime** et compte sur l'utilisateur pour être installé volontairement.", obj: "2.4" },
    { q: "Un ransomware a chiffré les données ET l'attaquant menace de publier les fichiers volés si la rançon n'est pas payée. Comment nomme-t-on cette pratique ?", o: ["Extorsion double", "Cryptojacking", "Logic bomb", "Bluesnarfing"], c: 0,
      e: "L'**extorsion double** combine **chiffrement** et **exfiltration** : même une restauration parfaite depuis les sauvegardes ne protège plus de la publication des données volées. C'est pourquoi la prévention de l'exfiltration (DLP) devient essentielle.", obj: "2.4" }
  ],

  /* ----------------------------- 7. Data Protection ------------------------ */
  7: [
    { q: "Une équipe de développement a besoin de données réalistes pour ses tests, sans jamais exposer de vraies données clients. Quelle technique appliquer ?", o: ["Le chiffrement intégral de disque", "Le data masking", "Le hachage", "La compression"], c: 1,
      e: "Le **data masking** conserve un **format réaliste et exploitable** tout en remplaçant les valeurs réelles. Le chiffrement rendrait les données inutilisables pour les tests, et le hachage détruirait irréversiblement le format.", obj: "3.3" },
    { q: "Une entreprise européenne stocke ses données dans un centre situé aux États-Unis. Quelles lois s'appliquent à ces données ?", o: ["Uniquement les lois européennes", "Les lois du pays où les données sont physiquement stockées", "Aucune loi particulière", "Uniquement les lois du pays du client"], c: 1,
      e: "Le principe de **data sovereignty** établit que les données sont soumises aux **lois du pays où elles sont physiquement stockées**. C'est pourquoi le choix de la région d'hébergement cloud est une décision de conformité majeure.", obj: "3.3" },
    { q: "Quelle protection s'applique à une donnée « in use » ?", o: ["TLS", "Chiffrement intégral de disque", "Chiffrement mémoire et secure enclave", "Sauvegarde hors site"], c: 2,
      e: "La donnée **in use** est **en mémoire, en cours de traitement**. Elle se protège par le **chiffrement mémoire** et l'usage d'une **secure enclave**. TLS protège la donnée **in transit**, le chiffrement de disque la donnée **at rest**.", obj: "3.3" },
    { q: "Un numéro de carte bancaire est remplacé par une valeur aléatoire, la vraie valeur étant conservée dans un coffre séparé qui permet de la retrouver. Quelle technique ?", o: ["Hachage", "Masking", "Tokenisation", "Stéganographie"], c: 2,
      e: "La **tokenisation** substitue un **jeton sans valeur exploitable** à la donnée réelle, laquelle reste dans un **coffre séparé** : l'opération est donc **réversible** via ce coffre. Le hachage, lui, est irréversible.", obj: "3.3" },
    { q: "Qui décide des finalités et des moyens d'un traitement de données personnelles ?", o: ["Le data processor", "Le data custodian", "Le data controller", "Le data subject"], c: 2,
      e: "Le **data controller décide des finalités et des moyens** du traitement. Le **processor** traite pour son compte sur instruction, le **custodian/steward** gère techniquement au quotidien, et le **data subject** est la personne concernée.", obj: "3.3" },
    { q: "Une organisation veut empêcher qu'un salarié copie des fichiers confidentiels sur une clé USB. Quelle solution déployer ?", o: ["Un IPS réseau", "Un DLP endpoint", "Un WAF", "Un serveur RADIUS"], c: 1,
      e: "Un **DLP endpoint** surveille et bloque les transferts de données sensibles **directement sur le poste**, y compris vers les supports amovibles. Un DLP réseau ne verrait pas une copie locale vers une clé USB.", obj: "3.3" },
    { q: "Pourquoi le hachage ne protège-t-il pas la confidentialité d'une donnée ?", o: ["Parce qu'il est trop lent", "Parce qu'il est irréversible et ne permet donc pas de restituer la donnée", "Parce qu'il utilise une clé publique", "Parce qu'il modifie le format"], c: 1,
      e: "Le hachage est **irréversible** : il sert à **prouver l'intégrité**, pas à protéger puis restituer une donnée. On ne « déhache » pas. Pour la confidentialité avec restitution, il faut du **chiffrement**.", obj: "3.3" },
    { q: "Une image contient un message caché de sorte que son existence même est indétectable à l'œil. Quelle technique ?", o: ["Tokenisation", "Stéganographie", "Masking", "Salting"], c: 1,
      e: "La **stéganographie** dissimule une information dans un autre fichier de manière à cacher **son existence même**. C'est ce qui la distingue du chiffrement, où l'on sait qu'un message existe mais sans pouvoir le lire.", obj: "3.3" },
    { q: "Classez ces données du niveau le plus ouvert au plus restreint selon la classification CompTIA.", o: ["Confidential, Public, Restricted", "Public, Sensitive, Restricted", "Restricted, Confidential, Public", "Private, Public, Sensitive"], c: 1,
      e: "**Public** est le niveau le plus ouvert, **Sensitive** implique déjà des restrictions, et **Restricted** est le plus fermé (accès strictement limité, souvent réglementé). Les autres propositions inversent cette progression.", obj: "3.3" }
  ],

  /* ------------------------ 8. Cryptographic Solutions --------------------- */
  8: [
    { q: "Alice veut envoyer un document confidentiel à Bob en utilisant la cryptographie asymétrique. Avec quelle clé doit-elle chiffrer ?", o: ["Sa propre clé privée", "Sa propre clé publique", "La clé publique de Bob", "La clé privée de Bob"], c: 2,
      e: "Pour la **confidentialité**, on chiffre avec la **clé publique du destinataire** : seul Bob, détenteur de la clé privée correspondante, pourra déchiffrer. Chiffrer avec sa propre clé privée reviendrait à **signer**, pas à protéger le contenu.", obj: "1.4" },
    { q: "Alice signe numériquement un contrat. Quelle clé utilise-t-elle et que garantit cette signature ?", o: ["La clé publique de Bob ; la confidentialité", "Sa propre clé privée ; authenticité, intégrité et non-répudiation", "Sa propre clé publique ; la disponibilité", "Une clé symétrique partagée ; la confidentialité"], c: 1,
      e: "On signe avec sa **propre clé privée**, et chacun vérifie avec la clé publique correspondante. La signature garantit l'**authenticité**, l'**intégrité** et la **non-répudiation** — mais **pas la confidentialité**, car le document reste lisible.", obj: "1.4" },
    { q: "Une entreprise doit chiffrer de très gros volumes de données rapidement. Quel type de chiffrement privilégier ?", o: ["Asymétrique, car plus sûr", "Symétrique, car beaucoup plus rapide", "Le hachage, car irréversible", "Aucun, la compression suffit"], c: 1,
      e: "Le chiffrement **symétrique** (AES) est **nettement plus rapide** et convient aux gros volumes. L'asymétrique, très coûteux en calcul, sert surtout à l'**échange de la clé symétrique** et à la **signature** — d'où les systèmes hybrides.", obj: "1.4" },
    { q: "Pourquoi ajoute-t-on un sel (salt) avant de hacher un mot de passe ?", o: ["Pour accélérer le calcul", "Pour rendre les rainbow tables inefficaces et différencier deux mots de passe identiques", "Pour permettre le déchiffrement", "Pour réduire la taille de l'empreinte"], c: 1,
      e: "Le **salting** ajoute une valeur aléatoire unique à chaque mot de passe. Les **rainbow tables** précalculées deviennent inutilisables, et **deux utilisateurs ayant le même mot de passe obtiennent des empreintes différentes**.", obj: "1.4" },
    { q: "Un administrateur veut vérifier en temps réel si un certificat précis a été révoqué, sans télécharger une longue liste. Quelle solution ?", o: ["CRL", "OCSP", "CSR", "PKCS#12"], c: 1,
      e: "L'**OCSP** interroge l'autorité **en temps réel sur un certificat précis**. La **CRL** est une liste complète téléchargée périodiquement, donc potentiellement périmée et volumineuse. Le CSR est une demande de certificat.", obj: "1.4" },
    { q: "Quelle information un CSR ne contient JAMAIS ?", o: ["La clé publique", "Le nom de domaine", "La clé privée", "Les informations d'identité de l'organisation"], c: 2,
      e: "Un **Certificate Signing Request** contient la **clé publique** et les informations d'identité, mais **jamais la clé privée** : celle-ci ne doit **jamais quitter le serveur** qui l'a générée. C'est un piège classique de l'examen.", obj: "1.4" },
    { q: "Une organisation a besoin d'un certificat couvrant www.exemple.com, mail.exemple.com et vpn.exemple.com. Quelle solution est la plus adaptée ?", o: ["Un certificat auto-signé", "Un certificat wildcard *.exemple.com", "Trois certificats racine", "Un certificat OCSP"], c: 1,
      e: "Un certificat **wildcard** (\\*.exemple.com) couvre **tous les sous-domaines d'un même niveau** avec un seul certificat. Un certificat **SAN** conviendrait aussi, mais il est indispensable dès lors que les **domaines de base diffèrent**.", obj: "1.4" },
    { q: "Quelle est la différence essentielle entre un TPM et un HSM ?", o: ["Le TPM est logiciel, le HSM matériel", "Le TPM est une puce liée à une machine unique, le HSM est un appareil dédié gérant les clés à grande échelle", "Le HSM ne gère que le chiffrement symétrique", "Il n'y a aucune différence"], c: 1,
      e: "Le **TPM** est une **puce soudée à la carte mère d'UNE machine** (chiffrement de disque, boot mesuré). Le **HSM** est un **appareil dédié**, souvent réseau ou amovible, conçu pour gérer les clés **à l'échelle de l'entreprise**.", obj: "1.4" },
    { q: "Un attaquant force un serveur à négocier TLS 1.0 au lieu de TLS 1.3 pour exploiter une faiblesse connue. Quelle attaque ?", o: ["Birthday attack", "Collision", "Downgrade", "Replay"], c: 2,
      e: "Forcer l'usage d'une **version de protocole ou d'un algorithme plus faible** est une attaque par **downgrade**. La parade consiste à **désactiver explicitement** les versions obsolètes côté serveur.", obj: "1.4" },
    { q: "Quel bénéfice principal ECC offre-t-il par rapport à RSA ?", o: ["Il est réversible", "Il offre une sécurité équivalente avec des clés bien plus courtes", "Il ne nécessite pas de clé privée", "Il remplace le hachage"], c: 1,
      e: "L'**ECC** atteint une sécurité comparable à RSA avec des **clés nettement plus courtes**, donc moins de calcul, moins de mémoire et moins d'énergie. C'est décisif pour les appareils **mobiles et IoT** aux ressources limitées.", obj: "1.4" },
    { q: "Que garantit la Perfect Forward Secrecy ?", o: ["Que la clé privée ne peut jamais être volée", "Qu'une clé de session compromise ne permet pas de déchiffrer les sessions passées", "Que le chiffrement est incassable", "Que les certificats n'expirent jamais"], c: 1,
      e: "La **PFS** garantit qu'une **clé de session compromise ne compromet pas les communications antérieures**, car chaque session utilise une clé éphémère indépendante. Elle est obtenue avec **DHE** et **ECDHE**.", obj: "1.4" },
    { q: "Deux fichiers différents produisent la même empreinte de hachage. Comment nomme-t-on ce phénomène et quel algorithme y est particulièrement vulnérable ?", o: ["Une collision ; MD5", "Un salt ; SHA-256", "Un downgrade ; AES", "Un replay ; RSA"], c: 0,
      e: "Une **collision** survient quand **deux entrées distinctes produisent la même empreinte**. **MD5** y est aujourd'hui trivialement vulnérable, et SHA-1 l'est également : tous deux sont proscrits pour un usage sécuritaire.", obj: "1.4" },
    { q: "Quel mécanisme rend volontairement le calcul d'un hachage de mot de passe lent et coûteux ?", o: ["Le salting", "Le key stretching", "La tokenisation", "Le key escrow"], c: 1,
      e: "Le **key stretching** (**PBKDF2**, **bcrypt**, **scrypt**, Argon2) impose un coût de calcul élevé, ce qui **ralentit massivement les attaques par force brute**. Le salting, lui, contre les tables précalculées : les deux sont complémentaires.", obj: "1.4" }
  ],

  /* ----------------------------- 9. Risk Management ------------------------ */
  9: [
    { q: "Un actif vaut 200 000 €. Un incendie détruirait 25 % de sa valeur et survient statistiquement tous les 10 ans. Quel est l'ALE ?", o: ["50 000 €", "5 000 €", "20 000 €", "500 €"], c: 1,
      e: "**SLE = AV × EF** = 200 000 × 0,25 = **50 000 €**. **ARO** = 1/10 = **0,1**. **ALE = SLE × ARO** = 50 000 × 0,1 = **5 000 € par an**. L'erreur classique consiste à s'arrêter au SLE (50 000 €).", obj: "5.2" },
    { q: "L'ALE d'un risque est de 30 000 €. Un fournisseur propose une solution à 40 000 € par an qui éliminerait totalement ce risque. Que recommander ?", o: ["Acheter la solution, la sécurité prime toujours", "Ne pas acheter : le coût du contrôle dépasse la perte annuelle attendue", "Acheter et augmenter le budget", "Ignorer complètement le risque"], c: 1,
      e: "Un contrôle n'est rentable que si son **coût annuel est inférieur à la réduction d'ALE** obtenue. Dépenser 40 000 € pour éviter 30 000 € de perte annuelle attendue n'est **pas justifié économiquement** : mieux vaut une mitigation partielle moins coûteuse ou un transfert.", obj: "5.2" },
    { q: "Une entreprise souscrit une cyber-assurance pour couvrir les conséquences financières d'une fuite de données. Quelle stratégie de risque applique-t-elle ?", o: ["Mitigate", "Avoid", "Transfer", "Accept"], c: 2,
      e: "L'assurance **déplace l'impact financier vers un tiers** : c'est un **transfert**. Attention, le risque **opérationnel et réputationnel demeure** : l'assurance ne restaure ni les systèmes ni la confiance des clients.", obj: "5.2" },
    { q: "Une organisation décide d'abandonner totalement un projet dont le niveau de risque est jugé inacceptable. Quelle stratégie ?", o: ["Accept", "Avoid", "Transfer", "Mitigate"], c: 1,
      e: "**Supprimer l'activité qui génère le risque** correspond à la stratégie **avoid** (éviter). C'est la seule stratégie qui ramène le risque à zéro, mais elle implique de renoncer au bénéfice attendu de l'activité.", obj: "5.2" },
    { q: "Une entreprise accepte de perdre au maximum 4 heures de données en cas de sinistre. Quelle métrique cela définit-il et qu'en déduit-on ?", o: ["Le RTO ; il faut restaurer en 4 heures", "Le RPO ; il faut sauvegarder au moins toutes les 4 heures", "Le MTTR ; il faut réparer en 4 heures", "Le MTBF ; une panne survient toutes les 4 heures"], c: 1,
      e: "Le **RPO** définit la **quantité maximale de données que l'on accepte de perdre**, exprimée en temps. Un RPO de 4 heures impose donc une **fréquence de sauvegarde d'au moins 4 heures**. Le RTO, lui, concerne le délai de remise en service.", obj: "5.2" },
    { q: "Quelle analyse détermine les fonctions critiques d'une organisation ainsi que les RTO et RPO associés ?", o: ["La gap analysis", "La business impact analysis", "Le risk register", "Le penetration test"], c: 1,
      e: "La **BIA (Business Impact Analysis)** identifie les **fonctions critiques**, évalue l'impact de leur interruption et fixe les **RTO et RPO**. Elle **précède** obligatoirement l'élaboration du plan de continuité.", obj: "5.2" },
    { q: "Une entreprise choisit systématiquement les options les moins risquées, quitte à limiter sa croissance. Comment qualifier son appétit au risque ?", o: ["Expansionary", "Neutral", "Conservative", "Aggressive"], c: 2,
      e: "Un appétit **conservative** privilégie la **prudence et la limitation du risque**, même au prix d'opportunités manquées. L'**expansionary** accepte davantage de risque pour croître, le **neutral** se situe entre les deux.", obj: "5.2" },
    { q: "Quel document recense les risques identifiés, leurs propriétaires, les indicateurs de suivi et les seuils d'acceptation ?", o: ["Le risk register", "Le SLA", "Le playbook", "Le BIA"], c: 0,
      e: "Le **risk register** centralise les risques identifiés, leur évaluation, les **KRI**, les **risk owners** et les **risk thresholds**. C'est l'outil de pilotage vivant de la gestion du risque.", obj: "5.2" },
    { q: "Quelle différence entre MTTR et MTBF ?", o: ["MTTR mesure le temps entre deux pannes, MTBF le temps de réparation", "MTTR mesure le temps moyen de réparation, MTBF le temps moyen entre deux pannes", "Les deux sont identiques", "MTBF concerne uniquement les logiciels"], c: 1,
      e: "Le **MTTR (Mean Time To Repair)** mesure la **rapidité de rétablissement** ; le **MTBF (Mean Time Between Failures)** mesure la **fiabilité** de l'équipement, c'est-à-dire l'intervalle moyen entre deux pannes.", obj: "5.2" },
    { q: "Une direction accorde une dérogation temporaire et documentée à une politique de mot de passe pour une application legacy. Comment nomme-t-on cela ?", o: ["Une exemption définitive", "Une exception", "Un transfert de risque", "Un compensating control"], c: 1,
      e: "Une **exception** est une **dérogation temporaire et justifiée** à une règle, assortie d'une échéance. L'**exemption** est une dispense **formelle et durable**. Dans les deux cas, la décision doit être documentée et acceptée par un responsable.", obj: "5.2" },
    { q: "Quel type d'analyse de risque utilise des échelles subjectives et une matrice probabilité × impact ?", o: ["Quantitative", "Qualitative", "Actuarielle", "Statistique"], c: 1,
      e: "L'analyse **qualitative** classe les risques sur des **échelles subjectives** (faible/moyen/élevé) via une matrice probabilité × impact. Elle est **rapide et peu coûteuse**, contrairement à l'analyse **quantitative** qui exige des valeurs monétaires précises.", obj: "5.2" }
  ],

  /* ------------------------ 10. Third-party Vendor Risks ------------------- */
  10: [
    { q: "Un contrat garantit une disponibilité de 99,9 % avec des pénalités financières en cas de manquement. De quel type d'accord s'agit-il ?", o: ["MOU", "SLA", "NDA", "BPA"], c: 1,
      e: "Un **SLA (Service-Level Agreement)** fixe des **engagements mesurables** de niveau de service, assortis de **pénalités**. Le MOU est une simple déclaration d'intention, le NDA porte sur la confidentialité, le BPA sur une relation de partenariat.", obj: "5.3" },
    { q: "Deux organisations signent un document décrivant leur intention de collaborer, sans créer d'obligation juridique contraignante. Quel accord ?", o: ["MSA", "SOW", "MOU", "SLA"], c: 2,
      e: "Le **MOU (Memorandum of Understanding)** est une **déclaration d'intention généralement non contraignante**. Le **MOA** serait plus formel et détaillerait les responsabilités de chacun.", obj: "5.3" },
    { q: "Une entreprise signe un contrat-cadre fixant les conditions générales applicables à tous les futurs projets avec un prestataire. Comment se nomme ce document ?", o: ["SOW", "MSA", "NDA", "MOU"], c: 1,
      e: "Le **MSA (Master Service Agreement)** est le **contrat-cadre** qui fixe les conditions générales une fois pour toutes. Chaque mission ultérieure fait ensuite l'objet d'un **SOW** détaillant livrables, calendrier et périmètre.", obj: "5.3" },
    { q: "Quand faut-il négocier une clause de droit d'audit (right-to-audit) avec un fournisseur ?", o: ["Après le premier incident de sécurité", "Avant la signature du contrat", "À la fin du contrat", "Uniquement si la loi l'exige"], c: 1,
      e: "La clause doit être négociée **AVANT la signature**, tant que le client dispose d'un levier de négociation. Une fois le contrat signé, le fournisseur n'a **plus aucune raison d'accepter** de s'y soumettre.", obj: "5.3" },
    { q: "Un attaquant compromet un éditeur pour distribuer une mise à jour piégée à tous ses clients. Quelle catégorie de risque tiers ?", o: ["Insider threat", "Supply chain attack", "Shadow IT", "Watering hole"], c: 1,
      e: "C'est une **attaque de la chaîne d'approvisionnement** : on compromet **un maillon de confiance** pour atteindre en cascade tous ses clients. L'affaire **SolarWinds** en est l'illustration la plus connue.", obj: "5.3" },
    { q: "Avant de retenir un prestataire, une entreprise vérifie sa santé financière, sa réputation et sa posture de sécurité. Comment nomme-t-on cette démarche ?", o: ["Due care", "Due diligence", "Attestation", "Right-to-audit"], c: 1,
      e: "La **due diligence** est l'**enquête approfondie menée AVANT de contractualiser**. La **due care** désigne au contraire l'**action raisonnable et continue** exercée ensuite, tout au long de la relation.", obj: "5.3" },
    { q: "Le suivi d'un fournisseur doit-il être ponctuel ou continu ?", o: ["Ponctuel, à la signature du contrat uniquement", "Continu, car la posture du fournisseur évolue dans le temps", "Uniquement après un incident", "Seulement lors du renouvellement"], c: 1,
      e: "Le **vendor monitoring est continu**. La conformité constatée à la signature **ne préjuge en rien** de la situation deux ans plus tard : il faut des questionnaires réguliers, des revues de performance et un suivi des incidents.", obj: "5.3" },
    { q: "Quel accord définit la répartition des profits et des responsabilités entre deux entreprises partenaires ?", o: ["SLA", "NDA", "BPA", "SOW"], c: 2,
      e: "Le **BPA (Business Partners Agreement)** régit la relation entre partenaires : apports respectifs, **responsabilités**, **répartition des profits** et modalités de sortie du partenariat.", obj: "5.3" },
    { q: "Pourquoi un MSP (Managed Service Provider) représente-t-il un risque particulièrement élevé ?", o: ["Il coûte cher", "Il détient des accès privilégiés permanents à vos systèmes", "Il est toujours situé à l'étranger", "Il ne signe jamais de NDA"], c: 1,
      e: "Un MSP dispose d'**accès privilégiés permanents** à l'infrastructure de ses clients. Le compromettre revient donc à **compromettre directement tous ses clients**, ce qui en fait une cible de choix pour les attaquants.", obj: "5.3" }
  ],

  /* ---------------------- 11. Governance and Compliance -------------------- */
  11: [
    { q: "Quel document décrit, étape par étape, COMMENT réaliser concrètement une tâche de sécurité ?", o: ["Une policy", "Un standard", "Une procedure", "Une guideline"], c: 2,
      e: "La **procedure** décrit le **COMMENT**, étape par étape. La **policy** énonce le **quoi et le pourquoi**, le **standard** fixe le **niveau exigé**, et la **guideline** propose des recommandations **facultatives**.", obj: "5.1" },
    { q: "Parmi ces documents de gouvernance, lequel n'est PAS obligatoire ?", o: ["La policy", "Le standard", "La procedure", "La guideline"], c: 3,
      e: "Les **guidelines sont des recommandations facultatives** qui aident à appliquer les règles. Les **policies, standards et procedures sont obligatoires** et leur non-respect est sanctionnable.", obj: "5.1" },
    { q: "Un employé signe un document attestant qu'il a lu et compris la charte informatique. De quoi s'agit-il ?", o: ["D'un SLA", "D'une attestation and acknowledgement", "D'un audit externe", "D'une gap analysis"], c: 1,
      e: "L'**attestation and acknowledgement** est la **confirmation formelle et signée** de la prise de connaissance des règles. Elle crée une **responsabilité traçable** et opposable en cas de manquement ultérieur.", obj: "5.4" },
    { q: "Quelle est la différence entre due diligence et due care ?", o: ["Ce sont deux synonymes", "La due diligence consiste à enquêter avant d'agir, la due care à agir raisonnablement et continûment ensuite", "La due care précède la due diligence", "La due diligence ne concerne que les audits"], c: 1,
      e: "La **due diligence** est l'**investigation préalable** (vérifier avant de s'engager) ; la **due care** est l'**action raisonnable et continue** menée ensuite. Les deux sont exigées pour démontrer qu'on a agi en bon professionnel.", obj: "5.4" },
    { q: "Une organisation adopte une gouvernance décentralisée. Quel inconvénient principal doit-elle anticiper ?", o: ["Une lenteur excessive des décisions", "Des incohérences et des lacunes de contrôle entre entités", "Un point unique de défaillance", "Une impossibilité d'auditer"], c: 1,
      e: "La décentralisation apporte **agilité et proximité du terrain**, mais génère des **incohérences, des duplications et des lacunes** de contrôle entre entités. La lenteur décisionnelle est au contraire le défaut du modèle **centralisé**.", obj: "5.1" },
    { q: "Sous le RGPD, comment se nomme la personne physique à laquelle se rapportent les données personnelles ?", o: ["Le data controller", "Le data processor", "Le data subject", "Le data custodian"], c: 2,
      e: "Le **data subject** est la **personne concernée** par les données. Le **controller** décide des finalités, le **processor** traite pour son compte, et le **custodian** assure la gestion technique quotidienne.", obj: "5.4" },
    { q: "Quelles sont les conséquences possibles d'une non-conformité réglementaire ?", o: ["Uniquement des amendes", "Amendes, sanctions, atteinte à la réputation, perte de licence et impacts contractuels", "Uniquement une atteinte à la réputation", "Aucune si l'entreprise corrige rapidement"], c: 1,
      e: "CompTIA retient cinq conséquences : **fines** (amendes), **sanctions**, **reputational damage**, **loss of license** et **contractual impacts**. Les conséquences non financières sont souvent les plus lourdes à long terme.", obj: "5.4" },
    { q: "Quel document définit ce qu'un employé a le droit et l'interdiction de faire avec les ressources informatiques de l'entreprise ?", o: ["Le SLA", "L'AUP", "Le BIA", "Le SOW"], c: 1,
      e: "L'**AUP (Acceptable Use Policy)** encadre l'**usage acceptable des ressources** de l'entreprise. C'est le document de référence lorsqu'il s'agit de sanctionner un usage abusif.", obj: "5.1" },
    { q: "Pourquoi une politique de sécurité doit-elle être révisée périodiquement ?", o: ["Pour satisfaire les auditeurs uniquement", "Parce qu'une politique obsolète donne une fausse impression de conformité", "Pour augmenter le nombre de documents", "Ce n'est pas nécessaire une fois validée"], c: 1,
      e: "Le **monitoring and revision** est une exigence de gouvernance : une politique non révisée **ne reflète plus la réalité** technique et réglementaire, ce qui crée une **fausse impression de conformité** particulièrement dangereuse.", obj: "5.1" },
    { q: "Un client européen demande la suppression complète de ses données personnelles. Quel droit invoque-t-il ?", o: ["Le droit d'accès", "Le droit à la portabilité", "Le droit à l'effacement (right to be forgotten)", "Le droit d'opposition au profilage"], c: 2,
      e: "Le **right to be forgotten** (droit à l'effacement) permet à une personne d'exiger la **suppression de ses données personnelles**. C'est l'un des piliers du **RGPD**, sous réserve des obligations légales de conservation.", obj: "5.4" }
  ],

  /* ------------------- 12. Asset and Change Management --------------------- */
  12: [
    { q: "Quel élément est INDISPENSABLE avant d'appliquer un changement en production ?", o: ["Un communiqué de presse", "Un backout plan", "Un audit externe", "Un nouveau SLA"], c: 1,
      e: "Le **backout plan** décrit **comment revenir à l'état antérieur** si le changement échoue. Sans lui, un échec se transforme en **panne prolongée** faute de solution de repli.", obj: "1.3" },
    { q: "Une entreprise doit effacer les données d'anciens SSD avant leur revente. Quelle méthode est INEFFICACE ?", o: ["Le cryptographic erase", "Le degaussing", "La destruction physique", "L'écrasement multiple certifié"], c: 1,
      e: "Le **degaussing** agit sur un **champ magnétique** : il est **totalement inefficace sur un SSD**, qui stocke en mémoire flash. Il faut recourir au **cryptographic erase** ou à la **destruction physique**.", obj: "4.2" },
    { q: "Pourquoi une allow list est-elle plus sûre qu'une deny list ?", o: ["Elle est plus rapide à configurer", "Elle interdit tout par défaut et n'autorise que l'explicitement listé", "Elle consomme moins de ressources", "Elle ne nécessite aucune maintenance"], c: 1,
      e: "L'**allow list bloque tout par défaut** : tout élément inconnu, y compris un malware zero-day, est refusé. La **deny list autorise tout sauf ce qui est listé**, et laisse donc passer **tout ce qui n'a pas encore été identifié**.", obj: "1.3" },
    { q: "Après avoir modifié l'architecture réseau, que doit impérativement faire l'équipe ?", o: ["Rien, le changement suffit", "Mettre à jour les diagrammes ainsi que les politiques et procédures", "Uniquement informer les utilisateurs", "Attendre le prochain audit"], c: 1,
      e: "La documentation doit être mise à jour : **diagrammes** ET **politiques/procédures**. Une documentation périmée constitue une **vulnérabilité** en soi, car elle induit en erreur lors d'un incident ou d'une investigation.", obj: "1.3" },
    { q: "Quel organe évalue et approuve les demandes de changement en pesant bénéfice et risque ?", o: ["Le SOC", "Le CAB", "Le CIRT", "Le comité d'audit"], c: 1,
      e: "Le **CAB (Change Advisory Board)** évalue et **approuve les changements**. Le SOC surveille et détecte, le CIRT répond aux incidents, le comité d'audit contrôle la conformité.", obj: "1.3" },
    { q: "Une entreprise détruit un disque contenant des données réglementées et reçoit un document prouvant l'opération. De quoi s'agit-il ?", o: ["D'un SLA", "D'un certificate of destruction", "D'un legal hold", "D'une attestation d'audit"], c: 1,
      e: "Le **certificate of destruction** est la **preuve documentaire** que le média a été détruit, mentionnant méthode, date et responsable. Il est indispensable pour démontrer la conformité en cas de contrôle.", obj: "4.2" },
    { q: "Quelle différence entre sanitization et destruction ?", o: ["Ce sont deux synonymes", "La sanitization efface les données en conservant le média, la destruction détruit physiquement le support", "La destruction est réversible", "La sanitization ne concerne que le papier"], c: 1,
      e: "La **sanitization rend les données irrécupérables tout en conservant le média** (réutilisable). La **destruction détruit physiquement le support** (broyage, incinération), qui devient inutilisable.", obj: "4.2" },
    { q: "Pourquoi la gestion des dépendances est-elle critique lors d'un changement ?", o: ["Elle accélère le déploiement", "Modifier un composant peut casser silencieusement les systèmes qui en dépendent", "Elle réduit les coûts", "Elle remplace le backout plan"], c: 1,
      e: "Les **dépendances** doivent être cartographiées dans l'**analyse d'impact** : un changement apparemment isolé peut **casser en cascade** des systèmes tiers qui reposent sur le composant modifié.", obj: "1.3" },
    { q: "Quel est le principal risque d'une politique de rétention des données trop longue ?", o: ["Un coût de stockage réduit", "Une exposition accrue en cas de fuite de données", "Une meilleure conformité", "Une restauration plus rapide"], c: 1,
      e: "Conserver **plus longtemps que nécessaire augmente le volume exposé** en cas de compromission. À l'inverse, une rétention trop courte viole les obligations légales et prive d'éléments d'investigation : c'est un équilibre à calibrer.", obj: "4.2" }
  ],

  /* ---------------------- 13. Audits and Assessments ---------------------- */
  13: [
    { q: "Un testeur d'intrusion reçoit les schémas réseau, le code source et des identifiants. De quel type de test s'agit-il ?", o: ["Unknown environment", "Partially known environment", "Known environment", "Passive reconnaissance"], c: 2,
      e: "Disposer de **toutes les informations** correspond au **known environment** (white box). C'est l'approche la plus **rapide et exhaustive**, mais la moins représentative d'un attaquant réel.", obj: "5.5" },
    { q: "Un analyste consulte LinkedIn, les enregistrements WHOIS et les moteurs de recherche pour cartographier une cible. Quelle activité mène-t-il ?", o: ["Reconnaissance active", "Reconnaissance passive", "Scan de vulnérabilités", "Exploitation"], c: 1,
      e: "Collecter des informations **sans jamais interagir avec les systèmes de la cible** est de la **reconnaissance passive**. Elle est **indétectable**. Dès que l'on scanne des ports ou que l'on énumère des services, on bascule en reconnaissance **active**, détectable.", obj: "5.5" },
    { q: "Quelle équipe attaque, laquelle défend, et laquelle fait collaborer les deux ?", o: ["Blue attaque, red défend, purple collabore", "Red attaque, blue défend, purple collabore", "Purple attaque, red défend, blue collabore", "Red attaque, purple défend, blue collabore"], c: 1,
      e: "La **red team attaque**, la **blue team défend et détecte**, et la **purple team fait collaborer les deux** pour améliorer la détection en continu. C'est un point de vocabulaire fréquemment testé.", obj: "5.5" },
    { q: "Quel document doit être signé AVANT le début d'un test d'intrusion ?", o: ["Le rapport final", "Les rules of engagement", "Le certificat de destruction", "Le risk register"], c: 1,
      e: "Les **rules of engagement** définissent **périmètre, horaires, méthodes autorisées et contacts d'urgence**. Sans ce document signé, le test peut être **juridiquement assimilé à une intrusion illégale**.", obj: "5.5" },
    { q: "Une déclaration formelle et signée affirmant que les conclusions d'un audit sont exactes se nomme :", o: ["Une gap analysis", "Une attestation", "Un playbook", "Un SLA"], c: 1,
      e: "L'**attestation** est la **déclaration formelle et signée** de l'exactitude des conclusions d'audit. Elle **engage la responsabilité du signataire**, ce qui lui donne toute sa valeur.", obj: "5.5" },
    { q: "Quelle est la principale finalité d'un audit externe indépendant ?", o: ["Réduire les coûts informatiques", "Apporter une crédibilité indépendante et démontrer la conformité aux tiers", "Remplacer les tests d'intrusion", "Former les employés"], c: 1,
      e: "L'audit **externe** apporte une **crédibilité indépendante** vis-à-vis des régulateurs, clients et partenaires. L'audit **interne**, lui, vise la **préparation et l'amélioration continue** avant ce regard extérieur.", obj: "5.5" },
    { q: "Quelle différence essentielle entre un audit et un test d'intrusion ?", o: ["L'audit est plus long", "L'audit vérifie la conformité à un référentiel, le pentest exploite réellement les failles pour démontrer l'impact", "Le pentest est toujours interne", "Il n'y a aucune différence"], c: 1,
      e: "L'**audit vérifie la conformité** à un référentiel, de façon largement documentaire et déclarative. Le **pentest exploite concrètement** les vulnérabilités et **démontre l'impact réel** ainsi que les chaînes d'attaque possibles.", obj: "5.5" },
    { q: "Quel type de pentest simule le plus fidèlement un attaquant externe réel ?", o: ["Known environment", "Partially known environment", "Unknown environment", "Audit interne"], c: 2,
      e: "L'**unknown environment** (black box) place le testeur dans la situation d'un **attaquant externe sans information préalable**. C'est le plus réaliste, mais aussi le plus long et le plus coûteux.", obj: "5.5" }
  ],

  /* ------------------ 14. Cyber Resilience and Redundancy ----------------- */
  14: [
    { q: "Une entreprise doit pouvoir reprendre son activité en moins de 2 heures après un sinistre majeur. Quel type de site de secours choisir ?", o: ["Cold site", "Warm site", "Hot site", "Aucun, les sauvegardes suffisent"], c: 2,
      e: "Seul un **hot site** permet une bascule en **minutes à quelques heures** : c'est une réplique opérationnelle avec des données à jour. Un warm site demande des heures à des jours, un cold site des jours à des semaines.", obj: "3.4" },
    { q: "Pourquoi le RAID ne remplace-t-il pas une sauvegarde ?", o: ["Parce qu'il est trop lent", "Parce qu'il réplique instantanément les suppressions et le chiffrement par ransomware", "Parce qu'il ne fonctionne que sur SSD", "Parce qu'il n'offre aucune tolérance de panne"], c: 1,
      e: "Le RAID protège de la **panne matérielle d'un disque**, mais il **réplique instantanément toute opération logique** : une suppression accidentelle ou un chiffrement par ransomware est immédiatement propagé sur tous les disques.", obj: "3.4" },
    { q: "Une organisation effectue un full le dimanche et des différentielles chaque soir. Une panne survient le jeudi. Que faut-il restaurer ?", o: ["Le full uniquement", "Le full et la différentielle de mercredi", "Le full et toutes les différentielles de la semaine", "Uniquement la différentielle de mercredi"], c: 1,
      e: "Une **différentielle contient tout ce qui a changé depuis le dernier FULL**. Il suffit donc de **deux jeux** : le full du dimanche et la **dernière différentielle** (mercredi soir). Avec des incrémentales, il aurait fallu le full plus **toutes** les incrémentales.", obj: "3.4" },
    { q: "Quelle différence entre un UPS et un générateur ?", o: ["L'UPS fournit une alimentation longue durée, le générateur une alimentation immédiate", "L'UPS fournit une alimentation immédiate mais courte, le générateur une alimentation longue mais différée", "Les deux sont identiques", "Le générateur ne sert qu'aux data centers"], c: 1,
      e: "L'**UPS prend le relais instantanément** grâce à ses batteries, mais seulement quelques minutes. Le **générateur tient longtemps** mais nécessite un **délai de démarrage**. C'est justement l'UPS qui couvre ce délai : les deux sont **complémentaires**.", obj: "3.4" },
    { q: "Quel test de continuité présente le risque le plus faible pour la production ?", o: ["Le failover réel", "Le parallel processing", "Le tabletop exercise", "La simulation complète"], c: 2,
      e: "Le **tabletop exercise** est une **discussion sur scénario autour d'une table** : il ne touche à **aucun système** et coûte très peu. Le failover réel, à l'inverse, bascule effectivement la production et comporte un risque d'interruption.", obj: "3.4" },
    { q: "Quelle configuration RAID tolère la perte de DEUX disques simultanément ?", o: ["RAID 0", "RAID 1", "RAID 5", "RAID 6"], c: 3,
      e: "Le **RAID 6** utilise une **double parité** et tolère donc la perte de **deux disques**. Le RAID 5 n'en tolère qu'un, le RAID 1 est un miroir simple, et le RAID 0 n'offre **aucune** tolérance de panne.", obj: "3.4" },
    { q: "Que signifie concrètement la règle 3-2-1 des sauvegardes ?", o: ["3 sauvegardes par jour, 2 par semaine, 1 par mois", "3 copies des données, sur 2 supports différents, dont 1 hors site", "3 serveurs, 2 sites, 1 administrateur", "3 heures de RTO, 2 heures de RPO, 1 test annuel"], c: 1,
      e: "La règle **3-2-1** impose **3 copies** des données, sur **2 types de supports différents**, dont **1 conservée hors site**. Elle protège simultanément de la panne matérielle, de l'erreur humaine et du sinistre local.", obj: "3.4" },
    { q: "Quelle différence entre load balancing et clustering ?", o: ["Le load balancing répartit la charge entre serveurs actifs, le clustering présente plusieurs serveurs comme un système unique avec bascule automatique", "Ce sont deux synonymes", "Le clustering ne concerne que le stockage", "Le load balancing assure la sauvegarde"], c: 0,
      e: "Le **load balancing répartit la charge** entre plusieurs serveurs actifs pour la performance. Le **clustering** fait apparaître plusieurs serveurs comme **un seul système** et assure la **bascule automatique** en cas de panne.", obj: "3.4" },
    { q: "Pourquoi la dispersion géographique des sites de secours est-elle indispensable ?", o: ["Pour réduire la latence réseau", "Pour qu'un même sinistre ne puisse pas affecter les deux sites simultanément", "Pour respecter le RGPD", "Pour diminuer les coûts d'hébergement"], c: 1,
      e: "La **geographic dispersion** garantit qu'un **sinistre régional** (séisme, inondation, panne électrique étendue) ne touche pas les deux sites en même temps. Un site de secours situé dans le même bâtiment ne protège de presque rien.", obj: "3.4" }
  ],

  /* ------------------------ 15. Security Architecture --------------------- */
  15: [
    { q: "Dans un modèle SaaS, de quoi le CLIENT reste-t-il responsable ?", o: ["Du système d'exploitation et des applications", "De l'infrastructure physique", "De ses données et de la gestion des accès", "De rien, le fournisseur gère tout"], c: 2,
      e: "En **SaaS**, le client ne gère plus que ses **données** et ses **identités et accès**. C'est une règle universelle : **dans TOUS les modèles cloud, les données et l'IAM restent la responsabilité du client**.", obj: "3.1" },
    { q: "Un attaquant parvient à s'échapper d'une machine virtuelle pour atteindre l'hyperviseur. Comment nomme-t-on cette attaque ?", o: ["Resource reuse", "VM escape", "Container breakout DNS", "Side loading"], c: 1,
      e: "La **VM escape** consiste à **sortir de la machine virtuelle pour atteindre l'hyperviseur** ou les autres VM du même hôte. C'est la vulnérabilité la plus grave en environnement virtualisé, car elle brise l'isolation fondamentale.", obj: "3.1" },
    { q: "Quelle différence essentielle entre une machine virtuelle et un conteneur ?", o: ["La VM est plus légère", "La VM embarque un OS complet, le conteneur partage le noyau de l'hôte", "Le conteneur offre une isolation plus forte", "Il n'y a aucune différence technique"], c: 1,
      e: "Une **VM embarque un OS complet** sur un hyperviseur : isolation forte mais lourde. Un **conteneur partage le noyau de l'hôte** : très léger et rapide, mais l'**isolation est plus faible** — une faille noyau affecte tous les conteneurs.", obj: "3.1" },
    { q: "Pourquoi la disponibilité prime-t-elle sur la confidentialité dans un environnement ICS/SCADA ?", o: ["Parce que les données industrielles n'ont aucune valeur", "Parce qu'un arrêt de production peut être dangereux pour les personnes et les installations", "Parce que le chiffrement y est interdit", "Parce que ces systèmes ne contiennent aucune donnée"], c: 1,
      e: "Dans un environnement industriel, une interruption peut provoquer des **conséquences physiques dangereuses** (accident, pollution, arrêt de chaîne). La **sûreté et la disponibilité** priment donc sur la confidentialité, contrairement à l'IT classique.", obj: "3.1" },
    { q: "Une équipe décrit l'ensemble de son infrastructure dans des fichiers de configuration versionnés. Quel bénéfice sécurité principal ?", o: ["Une réduction des coûts de licence", "Des déploiements reproductibles et l'élimination de la dérive de configuration", "Une augmentation de la bande passante", "La suppression du besoin de sauvegardes"], c: 1,
      e: "L'**Infrastructure as Code** rend les déploiements **reproductibles et auditables** et supprime la **dérive de configuration** (configuration drift). Chaque changement est tracé et revu comme du code.", obj: "3.1" },
    { q: "Que sépare une architecture SDN ?", o: ["Le réseau interne du réseau externe", "Le control plane (décision) du data plane (transfert)", "Les VLAN des sous-réseaux", "Le stockage du calcul"], c: 1,
      e: "Le **SDN sépare le control plane** (l'intelligence de décision de routage) du **data plane** (le transfert effectif des paquets), ce qui permet un **pilotage centralisé et programmable** du réseau.", obj: "3.1" },
    { q: "Un système est totalement déconnecté de tout réseau. Comment nomme-t-on cette protection et quelle est sa faiblesse ?", o: ["Segmentation logique ; les VLAN mal configurés", "Air gap ; les supports amovibles", "Micro-segmentation ; la latence", "DMZ ; les ports ouverts"], c: 1,
      e: "L'**air gap** est une **isolation physique totale**, la protection la plus forte qui soit. Sa faiblesse reste le **support amovible** : Stuxnet a franchi un air gap par clé USB.", obj: "3.1" },
    { q: "Quel est le principal risque de sécurité propre au serverless ?", o: ["L'impossibilité de chiffrer les données", "Une dépendance forte au fournisseur et une visibilité réduite sur l'infrastructure", "L'absence totale de journalisation", "L'obligation de gérer soi-même les correctifs"], c: 1,
      e: "Le serverless **supprime la charge de gestion de l'infrastructure** (le fournisseur patche à votre place, ce qui est un avantage), mais il crée une **dépendance forte au fournisseur** et **réduit la visibilité** sur ce qui se passe sous le capot.", obj: "3.1" },
    { q: "Pourquoi les objets IoT sont-ils des cibles privilégiées pour constituer des botnets ?", o: ["Ils disposent d'une grande puissance de calcul", "Identifiants par défaut, absence de mises à jour et déploiement massif", "Ils sont toujours chiffrés", "Ils utilisent des systèmes d'exploitation récents"], c: 1,
      e: "Les objets IoT cumulent **identifiants par défaut**, **ressources trop limitées** pour un chiffrement fort, **absence de mises à jour** et **déploiement massif**. Le botnet **Mirai** a exploité exactement cette combinaison.", obj: "3.1" },
    { q: "Quel est le principal inconvénient d'une architecture centralisée ?", o: ["Une trop grande agilité", "Un point unique de défaillance", "L'impossibilité d'auditer", "Une incohérence des configurations"], c: 1,
      e: "La centralisation apporte **cohérence et contrôle fort**, mais crée un **point unique de défaillance** et un goulet d'étranglement. L'incohérence des configurations est au contraire le défaut du modèle **décentralisé**.", obj: "3.1" }
  ],

  /* ----------------------- 16. Security Infrastructure -------------------- */
  16: [
    { q: "Quel port utilise LDAPS ?", o: ["389", "443", "636", "3389"], c: 2,
      e: "**LDAPS** (LDAP chiffré par TLS) utilise le port **636**. Le port **389** correspond au LDAP **en clair**, 443 à HTTPS et 3389 à RDP.", obj: "3.2" },
    { q: "Un IDS et un IPS sont installés sur le réseau. Quelle affirmation est correcte ?", o: ["L'IDS bloque le trafic, l'IPS se contente d'alerter", "L'IDS détecte et alerte en dérivation, l'IPS détecte et bloque en ligne", "Les deux bloquent le trafic de façon identique", "L'IPS est toujours passif"], c: 1,
      e: "L'**IDS détecte et alerte**, placé en **dérivation (tap)** : il est **passif**. L'**IPS détecte et BLOQUE**, placé **en ligne (inline)** sur le chemin du trafic : il est **actif**. C'est la distinction fondamentale.", obj: "3.2" },
    { q: "Une entreprise veut protéger son application web contre les injections SQL et le XSS. Quel équipement déployer ?", o: ["Un pare-feu de couche 4", "Un WAF", "Un serveur RADIUS", "Un jump server"], c: 1,
      e: "Le **WAF (Web Application Firewall)** inspecte le trafic HTTP/HTTPS et bloque spécifiquement les attaques **applicatives web** comme la **SQLi** et le **XSS**. Un pare-feu de couche 4 ne voit que les IP et les ports.", obj: "3.2" },
    { q: "Quels sont les trois acteurs du 802.1X ?", o: ["Client, serveur, routeur", "Supplicant, authenticator, authentication server", "Manager, agent, trap", "IdP, SP, subject"], c: 1,
      e: "Le **supplicant** est le client qui demande l'accès, l'**authenticator** est le switch ou le point d'accès qui contrôle le port, et l'**authentication server** (généralement RADIUS) prend la décision.", obj: "3.2" },
    { q: "Un pare-feu configuré en fail-closed tombe en panne. Que se passe-t-il ?", o: ["Tout le trafic passe librement", "Tout le trafic est bloqué", "Seul le trafic sortant passe", "Le pare-feu redémarre automatiquement"], c: 1,
      e: "En **fail-closed**, la panne **bloque tout le trafic** : la **sécurité prime sur la disponibilité**. En **fail-open**, le trafic passerait librement, privilégiant la continuité de service au détriment de la sécurité.", obj: "3.2" },
    { q: "Dans IPSec, quel composant assure le CHIFFREMENT des données ?", o: ["AH", "ESP", "IKE", "SPF"], c: 1,
      e: "**ESP (Encapsulating Security Payload)** assure le **chiffrement** (et peut aussi authentifier). **AH** ne fournit qu'**intégrité et authentification, sans chiffrement**. IKE sert à négocier les clés.", obj: "3.2" },
    { q: "Une entreprise veut que tout le trafic des télétravailleurs, y compris la navigation web personnelle, transite par le réseau d'entreprise. Quelle configuration VPN ?", o: ["Split tunnel", "Full tunnel", "Site-to-site", "Aucune, c'est impossible"], c: 1,
      e: "Le **full tunnel** fait passer **l'intégralité du trafic** par le VPN : plus sûr et permettant d'appliquer tous les contrôles d'entreprise, mais plus gourmand en bande passante. Le **split tunnel** ne route que le trafic d'entreprise.", obj: "3.2" },
    { q: "Quel équipement sert de point de rebond unique, durci et journalisé, pour administrer une zone sensible ?", o: ["Un reverse proxy", "Un jump server", "Un load balancer", "Un capteur passif"], c: 1,
      e: "Le **jump server** (bastion) **concentre et journalise tous les accès administratifs** vers une zone sensible. Il réduit la surface d'exposition et facilite la traçabilité des actions privilégiées.", obj: "3.2" },
    { q: "Un scanner détecte une attaque réelle mais l'IDS ne génère aucune alerte. Comment qualifier cette situation et pourquoi est-elle grave ?", o: ["Un faux positif ; elle fait perdre du temps", "Un faux négatif ; l'attaque passe inaperçue", "Un vrai positif ; le système fonctionne", "Un vrai négatif ; aucune action nécessaire"], c: 1,
      e: "Un **faux négatif** signifie qu'une **attaque réelle n'a pas été détectée**. C'est le cas le plus dangereux car il crée un **faux sentiment de sécurité**, contrairement au faux positif qui ne fait que générer du bruit.", obj: "3.2" },
    { q: "Quelle est la différence entre un forward proxy et un reverse proxy ?", o: ["Le forward proxy protège les serveurs entrants, le reverse proxy les clients sortants", "Le forward proxy protège les clients sortants, le reverse proxy les serveurs entrants", "Les deux sont identiques", "Le reverse proxy ne fonctionne qu'en UDP"], c: 1,
      e: "Le **forward proxy protège les CLIENTS** qui sortent vers Internet (filtrage, anonymisation, cache). Le **reverse proxy protège les SERVEURS** en recevant les requêtes entrantes (répartition de charge, terminaison TLS, masquage).", obj: "3.2" },
    { q: "Que combine le SASE ?", o: ["Un pare-feu et un antivirus locaux", "Le SD-WAN et des services de sécurité cloud délivrés en périphérie", "Un IDS et un IPS", "Un VPN et un serveur DHCP"], c: 1,
      e: "Le **SASE (Secure Access Service Edge)** combine le **SD-WAN** avec des **services de sécurité délivrés depuis le cloud** (SWG, CASB, ZTNA, FWaaS), au plus près de l'utilisateur, où qu'il se trouve.", obj: "3.2" },
    { q: "Quel port faut-il ouvrir pour permettre les transferts de zone DNS ?", o: ["UDP 53 uniquement", "TCP 53", "UDP 123", "TCP 443"], c: 1,
      e: "Les **requêtes DNS courantes utilisent UDP/53**, mais les **transferts de zone** et les réponses volumineuses passent par **TCP/53**. C'est une distinction régulièrement testée à l'examen.", obj: "3.2" }
  ],

  /* --------------- 17. Identity and Access Management (IAM) --------------- */
  17: [
    { q: "Un système exige un mot de passe puis la réponse à une question secrète. S'agit-il de MFA ?", o: ["Oui, il y a deux étapes", "Non, les deux relèvent du même facteur « something you know »", "Oui, car la question secrète est biométrique", "Non, il faut au moins trois facteurs"], c: 1,
      e: "Le MFA exige des facteurs de **catégories DIFFÉRENTES**. Un mot de passe et une question secrète relèvent tous deux de **« something you know »** : c'est une authentification en deux étapes, mais **pas du MFA**.", obj: "4.6" },
    { q: "Dans quel modèle de contrôle d'accès le PROPRIÉTAIRE du fichier décide-t-il qui peut y accéder ?", o: ["MAC", "DAC", "RBAC", "ABAC"], c: 1,
      e: "Le **DAC (Discretionary Access Control)** laisse le **propriétaire de la ressource** décider des accès. C'est le plus **souple** mais le **moins sûr**, car il dépend entièrement du jugement de chaque utilisateur.", obj: "4.6" },
    { q: "Une agence gouvernementale applique des labels de classification imposés par le système, qu'aucun utilisateur ne peut modifier. Quel modèle ?", o: ["DAC", "RBAC", "MAC", "Rule-based"], c: 2,
      e: "Le **MAC (Mandatory Access Control)** repose sur des **labels de classification imposés par le système**, hors de portée des utilisateurs. C'est le modèle le plus strict, typique des environnements militaires.", obj: "4.6" },
    { q: "Une entreprise attribue les droits selon la fonction occupée (comptable, RH, technicien). Quel modèle applique-t-elle ?", o: ["MAC", "DAC", "RBAC", "ABAC"], c: 2,
      e: "Le **RBAC (Role-Based Access Control)** attribue les droits via des **rôles métier**. C'est le modèle le plus répandu en entreprise car il **simplifie considérablement** la gestion des arrivées, mutations et départs.", obj: "4.6" },
    { q: "Une décision d'accès combine le service de l'utilisateur, l'heure de la demande, la sensibilité du document et le type d'appareil. Quel modèle ?", o: ["MAC", "RBAC", "ABAC", "DAC"], c: 2,
      e: "L'**ABAC (Attribute-Based Access Control)** combine des **attributs** de l'utilisateur, de la ressource et de l'environnement. C'est le modèle le plus **granulaire et dynamique**, au prix d'une complexité de mise en œuvre supérieure.", obj: "4.6" },
    { q: "Quelle affirmation distingue correctement OAuth de SAML ?", o: ["OAuth sert à l'authentification, SAML à l'autorisation", "OAuth sert à l'autorisation, SAML à l'authentification fédérée", "Les deux servent uniquement à l'authentification", "OAuth est un protocole de chiffrement"], c: 1,
      e: "**OAuth = AUTORISATION** (déléguer un accès sans partager son mot de passe). **SAML = AUTHENTIFICATION fédérée** par assertions XML. Pour authentifier avec OAuth, il faut lui ajouter la couche **OpenID Connect**.", obj: "4.6" },
    { q: "Un administrateur obtient des droits élevés uniquement pendant 30 minutes, à la demande, pour réaliser une opération précise. Quelle pratique PAM ?", o: ["Password vaulting", "Just-in-time permissions", "Federation", "Identity proofing"], c: 1,
      e: "Les **just-in-time permissions** accordent les privilèges **temporairement, à la demande et pour une durée limitée**, au lieu de les maintenir en permanence. Cela réduit drastiquement la fenêtre d'exploitation d'un compte compromis.", obj: "4.6" },
    { q: "Un employé change trois fois de service en cinq ans et cumule désormais tous les droits de ses anciens postes. Quel phénomène et quelle parade ?", o: ["Privilege escalation ; le chiffrement", "Privilege creep ; les revues d'accès périodiques", "Federation ; le SSO", "Identity proofing ; la biométrie"], c: 1,
      e: "Le **privilege creep** est l'**accumulation progressive de droits** au fil des mutations, faute de retrait des anciens. La parade consiste en des **revues d'accès (attestation) périodiques** et un de-provisioning rigoureux.", obj: "4.6" },
    { q: "En biométrie, quel taux représente le risque de sécurité le plus grave ?", o: ["Le FRR élevé, car il gêne les utilisateurs", "Le FAR élevé, car il laisse entrer des imposteurs", "Le CER, car il est théorique", "Aucun, la biométrie est infaillible"], c: 1,
      e: "Un **FAR (False Acceptance Rate) élevé** signifie que le système **accepte des imposteurs** : c'est un risque de sécurité direct. Un **FRR élevé** rejette des utilisateurs légitimes : c'est gênant, mais sans compromission.", obj: "4.6" },
    { q: "Quel protocole d'authentification utilise des tickets et un KDC, et exige une synchronisation horaire stricte ?", o: ["RADIUS", "Kerberos", "SAML", "OAuth"], c: 1,
      e: "**Kerberos** délivre des **tickets** via un **KDC** (l'utilisateur obtient d'abord un TGT). Il utilise le port **88** et est **très sensible à la désynchronisation des horloges** : un décalage de quelques minutes fait échouer l'authentification.", obj: "4.6" },
    { q: "Une tâche sensible est découpée de sorte qu'aucune personne seule ne puisse l'exécuter entièrement. Quel principe ?", o: ["Least privilege", "Separation of duties", "Federation", "Zero Trust"], c: 1,
      e: "La **separation of duties** répartit une opération sensible **entre plusieurs personnes** pour empêcher qu'un seul individu puisse commettre et dissimuler une fraude. Le **least privilege**, lui, limite les droits de chacun au strict nécessaire.", obj: "4.6" },
    { q: "Que se passe-t-il si le de-provisioning n'est pas rigoureusement appliqué au départ d'un salarié ?", o: ["Rien, les comptes expirent seuls", "Des comptes orphelins restent actifs et exploitables", "Le SSO cesse de fonctionner", "Les mots de passe se réinitialisent"], c: 1,
      e: "Un de-provisioning négligé laisse des **comptes orphelins actifs**, qui ne sont plus surveillés par personne. Ils constituent une **porte d'entrée idéale**, notamment pour un ancien employé mécontent.", obj: "4.6" }
  ],

  /* -------------------- 18. Vulnerabilities and Attacks ------------------- */
  18: [
    { q: "Quelle est la contre-mesure la PLUS efficace contre l'injection SQL ?", o: ["Chiffrer la base de données", "Utiliser des requêtes paramétrées (prepared statements)", "Installer un antivirus sur le serveur", "Renommer les tables de la base"], c: 1,
      e: "Les **requêtes paramétrées** séparent structurellement le **code SQL des données**, ce qui rend l'injection impossible par construction. La validation des entrées et le moindre privilège sur le compte SQL viennent en renfort, mais ne suffisent pas seuls.", obj: "2.3" },
    { q: "Un attaquant exploite le fait que l'état d'un fichier change entre le moment de sa vérification et celui de son utilisation. Quelle vulnérabilité ?", o: ["Buffer overflow", "Race condition TOC/TOU", "Memory injection", "Directory traversal"], c: 1,
      e: "Le **TOC/TOU (Time-of-Check to Time-of-Use)** est une **race condition** où l'attaquant **substitue la ressource entre la vérification et l'utilisation**. Le programme agit alors sur un objet différent de celui qu'il a validé.", obj: "2.3" },
    { q: "Un script malveillant est stocké dans un commentaire de forum et s'exécute dans le navigateur de chaque visiteur. Quel type d'attaque ?", o: ["XSS stored", "XSS reflected", "CSRF", "SQLi"], c: 0,
      e: "Le script est **stocké de façon persistante** sur le serveur et servi à **tous les visiteurs** : c'est un **XSS stored** (persistant), le plus dangereux car il touche massivement. Le **reflected** nécessiterait un lien piégé envoyé à chaque victime.", obj: "2.3" },
    { q: "Quelle affirmation distingue correctement XSS et CSRF ?", o: ["Le XSS exploite la confiance du site envers l'utilisateur, le CSRF l'inverse", "Le XSS exploite la confiance de l'utilisateur envers le site, le CSRF la confiance du site envers l'utilisateur", "Les deux exploitent la même confiance", "Le CSRF ne concerne que les API"], c: 1,
      e: "Le **XSS exploite la confiance de l'UTILISATEUR envers le site** (on injecte un script que la victime exécute). Le **CSRF exploite la confiance du SITE envers l'utilisateur authentifié** (on force une action à son insu).", obj: "2.3" },
    { q: "Pourquoi une détection par signature est-elle inefficace contre une vulnérabilité zero-day ?", o: ["Parce que les signatures sont trop nombreuses", "Parce qu'aucune signature n'existe encore pour une menace inconnue", "Parce que le zero-day est toujours chiffré", "Parce que les signatures ne fonctionnent qu'en réseau"], c: 1,
      e: "Un **zero-day est inconnu de l'éditeur** : **aucune signature n'a pu être écrite**. Seule une détection **comportementale ou par anomalie** peut repérer l'activité inhabituelle qu'il engendre.", obj: "2.3" },
    { q: "Un attaquant écrit au-delà de la mémoire allouée pour détourner l'exécution d'un programme. Quelles protections système contrent cela ?", o: ["SPF et DKIM", "ASLR et DEP", "TLS et IPSec", "RAID et UPS"], c: 1,
      e: "L'**ASLR** (randomisation de l'espace d'adressage) et le **DEP** (interdiction d'exécuter des zones de données) sont les protections système de référence contre le **buffer overflow**, complétées par la validation des entrées côté code.", obj: "2.3" },
    { q: "Un utilisateur installe une application depuis un site tiers plutôt que depuis le magasin officiel. Comment nomme-t-on cette pratique ?", o: ["Jailbreaking", "Side loading", "Rooting", "Sandboxing"], c: 1,
      e: "Le **side loading** consiste à installer une application **hors du magasin officiel**, donc **sans les contrôles de sécurité** de la plateforme. Le jailbreaking et le rooting, eux, retirent les restrictions du système d'exploitation.", obj: "2.3" },
    { q: "Quelle attaque Bluetooth consiste à VOLER des données sur l'appareil de la victime ?", o: ["Bluejacking", "Bluesnarfing", "Bluebugging", "Bluecasting"], c: 1,
      e: "Le **bluesnarfing** est le **VOL de données** via Bluetooth. Le **bluejacking** se limite à l'envoi de messages non sollicités (nuisance), et le **bluebugging** va plus loin en prenant le **contrôle** de l'appareil.", obj: "2.3" },
    { q: "Une entreprise ne peut pas remplacer un automate industriel vulnérable et non patchable. Quelle approche adopter ?", o: ["Ignorer le risque", "Le segmenter strictement et appliquer des contrôles compensatoires", "Le connecter directement à Internet pour faciliter la supervision", "Désactiver tous les journaux"], c: 1,
      e: "Quand le correctif est impossible, on applique des **compensating controls** : **segmentation stricte**, filtrage, surveillance renforcée et restriction des accès. C'est l'approche standard pour les systèmes legacy et ICS.", obj: "2.5" },
    { q: "Quelle est la cause la plus fréquente de compromission en environnement cloud ?", o: ["La faiblesse des algorithmes de chiffrement", "La mauvaise configuration (buckets publics, permissions trop larges)", "Les pannes matérielles du fournisseur", "L'absence de pare-feu chez le fournisseur"], c: 1,
      e: "La **misconfiguration** domine largement : stockages rendus publics par erreur, permissions IAM trop larges, services de gestion exposés. Elle relève de la **responsabilité du client**, pas du fournisseur.", obj: "2.3" }
  ],

  /* ------------------------- 19. Malicious Activity ----------------------- */
  19: [
    { q: "Les journaux montrent une connexion d'un même compte depuis Paris puis, huit minutes plus tard, depuis Singapour. Quel indicateur est-ce ?", o: ["Concurrent session usage", "Impossible travel", "Out-of-cycle logging", "Resource consumption"], c: 1,
      e: "L'**impossible travel** désigne deux connexions depuis des lieux **géographiquement incompatibles** dans un délai trop court. C'est un indicateur quasi certain de **compte compromis** ou d'usage d'un VPN/proxy par un attaquant.", obj: "2.4" },
    { q: "Un attaquant essaie le mot de passe « Été2024! » sur 5 000 comptes différents, à raison d'une seule tentative par compte. Quelle attaque et pourquoi est-elle efficace ?", o: ["Brute force ; elle est rapide", "Password spraying ; elle évite le verrouillage de compte", "Rainbow table ; elle est précalculée", "Credential replay ; elle rejoue une session"], c: 1,
      e: "Le **password spraying** teste **UN mot de passe courant sur BEAUCOUP de comptes**. Comme chaque compte ne subit qu'une tentative, le **verrouillage automatique ne se déclenche pas** et l'attaque passe sous les radars.", obj: "2.4" },
    { q: "Un analyste constate que les journaux de sécurité d'un serveur ont disparu pour une période de six heures. Que faut-il en conclure en priorité ?", o: ["Un problème de disque", "Une possible tentative d'effacement de traces par un attaquant", "Une mise à jour automatique", "Un changement de fuseau horaire"], c: 1,
      e: "Des **missing logs** constituent un **indicateur fort de compromission** : l'effacement des traces est une étape classique post-intrusion. Il faut le traiter comme un incident tant que l'hypothèse technique n'est pas formellement écartée.", obj: "2.4" },
    { q: "Un attaquant envoie de petites requêtes DNS en usurpant l'IP de sa victime, laquelle reçoit alors d'énormes réponses. Quelle attaque ?", o: ["DDoS amplifié et réfléchi", "On-path", "DNS tunneling", "Directory traversal"], c: 0,
      e: "L'attaque combine la **réflexion** (usurper l'IP de la victime pour que les réponses lui soient envoyées) et l'**amplification** (une petite requête produit une grosse réponse). Le DNS est un vecteur privilégié pour ce type d'attaque.", obj: "2.4" },
    { q: "Un employé accède aux dossiers d'un collègue de même niveau hiérarchique en manipulant un identifiant dans l'URL. Quel type d'escalade ?", o: ["Escalade verticale", "Escalade horizontale", "Directory traversal", "Privilege creep"], c: 1,
      e: "Accéder aux données d'un **autre utilisateur de même niveau de privilège** est une **escalade horizontale**. L'escalade **verticale** consisterait à obtenir des **droits supérieurs** (passer d'utilisateur à administrateur).", obj: "2.4" },
    { q: "Un point d'accès sans fil diffuse le même SSID que le réseau légitime de l'entreprise pour capter les connexions. Quelle attaque ?", o: ["Rogue AP", "Evil twin", "Deauthentication", "Bluesnarfing"], c: 1,
      e: "L'**evil twin imite le SSID légitime** pour tromper les clients. Le **rogue AP** est un point d'accès **non autorisé branché sur le réseau** de l'entreprise : la nuance porte sur l'imitation du SSID.", obj: "2.4" },
    { q: "Un attaquant exfiltre des données en les dissimulant dans des requêtes DNS sortantes. Quel indicateur permettrait de le détecter ?", o: ["Une baisse du trafic HTTP", "Des requêtes DNS anormalement nombreuses, longues ou vers un domaine inconnu", "Une augmentation du nombre d'utilisateurs", "Des redémarrages fréquents"], c: 1,
      e: "Le **DNS tunneling** génère des **requêtes anormalement nombreuses, longues et adressées à un domaine inhabituel**. Comme le port 53 est presque toujours autorisé en sortie, seule l'analyse du profil des requêtes le révèle.", obj: "2.4" },
    { q: "Quelle contre-mesure protège efficacement contre les rainbow tables ?", o: ["Le key stretching seul", "Le salting", "Le chiffrement asymétrique", "La compression"], c: 1,
      e: "Le **salting** ajoute une valeur aléatoire unique par mot de passe, ce qui rend **inutilisables les tables de hachages précalculés**. Le **key stretching** complète en ralentissant le calcul, mais c'est bien le sel qui neutralise les rainbow tables.", obj: "2.4" },
    { q: "Un attaquant capture puis réémet un jeton d'authentification valide pour usurper une session. Quelle attaque et quelle parade ?", o: ["On-path ; le chiffrement", "Replay ; les nonces et horodatages", "Brute force ; la complexité des mots de passe", "Forgery ; la signature numérique"], c: 1,
      e: "L'**attaque par rejeu (replay)** consiste à **réémettre des données d'authentification capturées**. Les **nonces** (valeurs à usage unique) et les **horodatages** garantissent qu'un message capturé ne peut pas être réutilisé.", obj: "2.4" },
    { q: "Que révèle l'indicateur « resource inaccessibility » sur un serveur de fichiers ?", o: ["Une simple surcharge réseau", "Un possible ransomware ou déni de service", "Une mise à jour en cours", "Un changement de mot de passe"], c: 1,
      e: "Des ressources **soudainement inaccessibles** évoquent en priorité un **ransomware** (fichiers chiffrés) ou un **déni de service**. Couplée à une consommation anormale ou à des extensions de fichiers modifiées, l'hypothèse du ransomware devient prioritaire.", obj: "2.4" },
    { q: "Quelle attaque consiste à envoyer des trames forçant la déconnexion des clients Wi-Fi ?", o: ["Deauthentication attack", "Evil twin", "ARP poisoning", "DNS poisoning"], c: 0,
      e: "La **deauthentication attack** force les clients à se **déconnecter** pour capturer le **handshake** lors de leur reconnexion, ou pour les pousser vers un **evil twin**. WPA3 et le 802.11w (Protected Management Frames) atténuent cette attaque.", obj: "2.4" }
  ],

  /* ------------------------------ 20. Hardening --------------------------- */
  20: [
    { q: "Quelles sont les trois étapes de la gestion d'une secure baseline ?", o: ["Créer, chiffrer, archiver", "Establish, deploy, maintain", "Scanner, patcher, auditer", "Identifier, contenir, éradiquer"], c: 1,
      e: "Le cycle est **Establish** (définir la configuration de référence), **Deploy** (l'appliquer au parc) et **Maintain** (surveiller la dérive et l'actualiser). La dernière étape est souvent négligée alors qu'elle est essentielle.", obj: "4.1" },
    { q: "Pourquoi ne faut-il jamais déployer un correctif directement en production ?", o: ["Parce que cela coûte plus cher", "Parce qu'un correctif peut casser une application ou provoquer une régression", "Parce que c'est interdit par le RGPD", "Parce que les correctifs sont toujours malveillants"], c: 1,
      e: "Un correctif peut provoquer une **régression ou une incompatibilité applicative**. Le passage en **préproduction** permet de le vérifier avant d'exposer la production : sans cela, une correction de sécurité peut se transformer en panne majeure.", obj: "4.1" },
    { q: "Un portable chiffré en FDE est volé alors qu'il était allumé et la session ouverte. Les données sont-elles protégées ?", o: ["Oui, le FDE protège en toutes circonstances", "Non, le FDE protège une machine éteinte, pas une session déverrouillée", "Oui, si le mot de passe est complexe", "Non, le FDE ne protège jamais rien"], c: 1,
      e: "Le **FDE protège les données d'une machine ÉTEINTE**. Une fois le système démarré et la session ouverte, **les données sont déchiffrées à la volée** et donc accessibles. D'où l'importance du verrouillage automatique de session.", obj: "4.1" },
    { q: "Quel mode SELinux journalise les violations sans les bloquer ?", o: ["Enforcing", "Permissive", "Disabled", "Targeted"], c: 1,
      e: "Le mode **permissive journalise les violations sans bloquer** : c'est le mode de mise au point avant bascule. **Enforcing** applique et bloque réellement, **disabled** désactive complètement SELinux.", obj: "4.1" },
    { q: "Pourquoi une application allow list protège-t-elle même contre un malware zero-day ?", o: ["Parce qu'elle utilise des signatures à jour", "Parce que seuls les exécutables explicitement autorisés peuvent s'exécuter", "Parce qu'elle chiffre les fichiers", "Parce qu'elle bloque le réseau"], c: 1,
      e: "L'**allow list bloque tout par défaut**. Un malware inconnu, même sans aucune signature existante, **n'est pas dans la liste et ne peut donc pas s'exécuter**. C'est ce qui la rend supérieure à toute approche par liste noire.", obj: "2.5" },
    { q: "Quel outil permet d'appliquer de façon centralisée des configurations de sécurité à tous les postes d'un domaine Windows ?", o: ["SELinux", "Group Policy (GPO)", "SCAP", "NetFlow"], c: 1,
      e: "Les **GPO (Group Policy Objects)** appliquent de manière **centralisée et automatique** les configurations de sécurité dans un domaine Windows. SELinux est l'équivalent conceptuel sous Linux, mais fonctionne différemment.", obj: "4.1" },
    { q: "Quelle mesure de durcissement est la plus efficace pour réduire la surface d'attaque d'un serveur ?", o: ["Augmenter la RAM", "Désinstaller les logiciels inutiles et désactiver les services non nécessaires", "Changer l'adresse IP", "Ajouter un second antivirus"], c: 1,
      e: "**Ce qui n'est pas installé ne peut pas être vulnérable.** Supprimer les logiciels inutiles et désactiver les services non nécessaires **élimine directement** des points d'entrée, plutôt que d'ajouter une couche de protection par-dessus.", obj: "2.5" },
    { q: "Qu'est-ce que le configuration enforcement ?", o: ["Chiffrer les fichiers de configuration", "Vérifier en continu la conformité à la référence et corriger automatiquement les dérives", "Sauvegarder les configurations", "Documenter les configurations"], c: 1,
      e: "Le **configuration enforcement** **détecte et corrige automatiquement** tout écart par rapport à la configuration de référence. Il empêche la **dérive progressive** qui, avec le temps, ruine l'efficacité d'une baseline pourtant bien conçue.", obj: "2.5" },
    { q: "Pourquoi l'isolation constitue-t-elle une mitigation efficace après une compromission ?", o: ["Elle supprime le malware", "Elle empêche la propagation latérale vers le reste du réseau", "Elle restaure les données", "Elle chiffre les communications"], c: 1,
      e: "L'**isolation empêche le mouvement latéral** : un système compromis mais isolé ne peut pas contaminer les autres. Elle ne supprime pas la menace (c'est le rôle de l'éradication) mais **limite immédiatement son périmètre**.", obj: "2.5" }
  ],

  /* -------------------------- 21. Security Techniques --------------------- */
  21: [
    { q: "Quel mécanisme WPA3 remplace le PSK et protège contre les attaques par dictionnaire hors ligne ?", o: ["TKIP", "SAE", "WEP", "WPS"], c: 1,
      e: "Le **SAE (Simultaneous Authentication of Equals)** remplace le PSK dans WPA3. Il empêche la **capture du handshake pour une attaque par dictionnaire hors ligne** et fournit la **forward secrecy**.", obj: "4.1" },
    { q: "Une entreprise veut que chaque utilisateur Wi-Fi s'authentifie avec son compte personnel et non une clé partagée. Quelle solution ?", o: ["WPA3-Personal avec une clé longue", "WPA2/WPA3-Enterprise avec 802.1X et RADIUS", "WEP avec filtrage MAC", "Un réseau ouvert avec portail captif"], c: 1,
      e: "Le mode **Enterprise** s'appuie sur le **802.1X avec un serveur RADIUS** et un **compte individuel** par utilisateur. Cela permet la révocation ciblée d'un accès et une traçabilité par personne, impossibles avec une clé partagée.", obj: "4.1" },
    { q: "Quel est le rôle respectif de SPF, DKIM et DMARC ?", o: ["SPF chiffre, DKIM signe, DMARC archive", "SPF déclare les serveurs autorisés, DKIM signe le message, DMARC définit la politique en cas d'échec", "SPF signe, DKIM déclare, DMARC chiffre", "Les trois font exactement la même chose"], c: 1,
      e: "**SPF** publie dans le DNS la **liste des serveurs autorisés à envoyer** pour le domaine. **DKIM** appose une **signature cryptographique** sur le message. **DMARC** indique **quoi faire en cas d'échec** (none, quarantine, reject) et organise le reporting.", obj: "4.5" },
    { q: "Quelle politique DMARC refuse purement et simplement les messages non conformes ?", o: ["none", "quarantine", "reject", "block"], c: 2,
      e: "La politique **reject** fait **refuser le message** par le serveur destinataire. **quarantine** le place en indésirable, **none** se contente d'observer et de générer des rapports sans agir.", obj: "4.5" },
    { q: "Un poste ne dispose pas des correctifs requis. Le système l'empêche d'accéder au réseau et le place en zone de remédiation. Quelle technologie ?", o: ["DLP", "NAC", "SIEM", "WAF"], c: 1,
      e: "Le **NAC (Network Access Control)** vérifie la **conformité d'un poste avant de l'admettre** sur le réseau (antivirus, correctifs, chiffrement). Un poste non conforme est **mis en quarantaine ou en remédiation**.", obj: "4.5" },
    { q: "Quelle différence entre EDR et XDR ?", o: ["L'EDR couvre le cloud, l'XDR les endpoints", "L'EDR surveille les endpoints, l'XDR corrèle en plus réseau, cloud et messagerie", "Les deux sont identiques", "L'XDR ne fait que de la sauvegarde"], c: 1,
      e: "L'**EDR** se concentre sur la détection et la réponse **sur les endpoints**. L'**XDR étend et corrèle** ces données avec le **réseau, le cloud et la messagerie**, offrant une vision d'ensemble de la chaîne d'attaque.", obj: "4.5" },
    { q: "Quel attribut de cookie empêche son accès par du JavaScript, limitant ainsi le vol de session par XSS ?", o: ["Secure", "HttpOnly", "SameSite", "Domain"], c: 1,
      e: "L'attribut **HttpOnly** rend le cookie **inaccessible au JavaScript**, ce qui neutralise le vol de session par XSS. **Secure** impose HTTPS et **SameSite** limite l'envoi cross-site (protection CSRF).", obj: "4.1" },
    { q: "Une équipe analyse le code source d'une application sans jamais l'exécuter. De quelle technique s'agit-il ?", o: ["DAST", "SAST", "Fuzzing", "Pentest"], c: 1,
      e: "L'analyse **statique (SAST)** examine le **code source sans exécution**, très tôt dans le cycle de développement. Le **DAST** teste au contraire l'application **en fonctionnement** et révèle des failles liées à l'environnement réel.", obj: "4.1" },
    { q: "Pourquoi réaliser un site survey avant de déployer un réseau Wi-Fi d'entreprise ?", o: ["Pour choisir la couleur des bornes", "Pour éliminer les zones mortes et éviter que le signal ne déborde hors du bâtiment", "Pour réduire le coût des licences", "Pour configurer le DHCP"], c: 1,
      e: "Le **site survey** mesure la couverture réelle afin d'éliminer les **zones mortes**, limiter les **interférences** et surtout **éviter le débordement du signal hors du bâtiment**, où un attaquant pourrait le capter depuis l'extérieur.", obj: "4.1" },
    { q: "Quel modèle de déploiement mobile offre le meilleur contrôle à l'entreprise ?", o: ["BYOD", "COPE", "CYOD", "Aucun, ils sont équivalents"], c: 1,
      e: "En **COPE (Corporate-Owned, Personally Enabled)**, l'entreprise **possède l'appareil** : elle peut donc imposer toutes ses politiques sans se heurter à la vie privée du salarié, contrairement au **BYOD** où l'appareil appartient à l'employé.", obj: "4.1" },
    { q: "Une solution établit un profil comportemental de chaque utilisateur et alerte en cas d'écart. De quoi s'agit-il ?", o: ["DLP", "UBA/UEBA", "FIM", "NAC"], c: 1,
      e: "L'**UBA/UEBA** construit une **base comportementale** puis alerte sur les **écarts** (horaires inhabituels, volumes anormaux, accès inédits). C'est particulièrement efficace contre les **menaces internes** et les **comptes compromis**.", obj: "4.5" },
    { q: "Quel outil alerte dès qu'un fichier système critique est modifié ?", o: ["FIM", "DLP", "NetFlow", "SPF"], c: 0,
      e: "Le **FIM (File Integrity Monitoring)** surveille les fichiers critiques et **alerte à toute modification**. C'est un indicateur précieux de compromission, notamment pour détecter l'installation d'une porte dérobée.", obj: "4.5" }
  ],

  /* ----------------------- 22. Vulnerability Management ------------------- */
  22: [
    { q: "Un scan signale une vulnérabilité qui, après vérification, n'existe pas réellement. Comment nomme-t-on cela ?", o: ["Un faux négatif", "Un faux positif", "Un vrai positif", "Un zero-day"], c: 1,
      e: "Un **faux positif** est une **alerte sur une vulnérabilité inexistante**. Il fait perdre du temps mais reste sans danger direct. Le **faux négatif**, qui rate une vraie vulnérabilité, est bien plus grave.", obj: "4.3" },
    { q: "Un scan authentifié (credentialed) présente quel avantage principal ?", o: ["Il est plus rapide", "Il offre une vue interne complète avec beaucoup moins de faux positifs", "Il ne nécessite aucune configuration", "Il est indétectable"], c: 1,
      e: "Le scan **credentialed** se connecte au système et **inspecte réellement les versions et configurations installées** : la précision est bien supérieure et les faux positifs bien moindres qu'avec un scan externe non authentifié.", obj: "4.3" },
    { q: "Une vulnérabilité obtient un score CVSS de 9,4. Dans quelle catégorie de sévérité se situe-t-elle ?", o: ["Medium", "High", "Critical", "Low"], c: 2,
      e: "L'échelle CVSS place **9,0 à 10,0 en Critical**. Les tranches sont : 0 = None, 0,1-3,9 = **Low**, 4,0-6,9 = **Medium**, 7,0-8,9 = **High**, 9,0-10,0 = **Critical**.", obj: "4.3" },
    { q: "Faut-il prioriser les correctifs uniquement selon le score CVSS ?", o: ["Oui, le CVSS suffit toujours", "Non, il faut aussi tenir compte de l'exposition réelle, du contexte et de l'impact métier", "Non, seul l'ordre alphabétique compte", "Oui, si le score dépasse 7"], c: 1,
      e: "Le CVSS donne une **gravité théorique**. La priorisation réelle doit intégrer l'**exposure factor**, les **environmental variables**, l'**impact métier et sectoriel** et la **risk tolerance**. Un CVSS 9 sur un système isolé peut être moins urgent qu'un CVSS 6 sur un serveur exposé.", obj: "4.3" },
    { q: "Après avoir appliqué un correctif, quelle étape est indispensable ?", o: ["Archiver le ticket", "Effectuer un nouveau scan pour valider la remédiation", "Informer le fournisseur", "Supprimer les journaux"], c: 1,
      e: "La **validation par rescanning** (complétée par audit et vérification) est indispensable. Sans nouveau scan, la correction n'est **pas prouvée** : elle est seulement supposée, ce qui est insuffisant en gestion des vulnérabilités.", obj: "4.3" },
    { q: "Une entreprise ne peut pas patcher un système critique. Quelle réponse est appropriée ?", o: ["Ignorer la vulnérabilité", "Mettre en place des compensating controls et documenter une exception", "Supprimer le système immédiatement", "Désactiver les journaux du système"], c: 1,
      e: "Quand le correctif est impossible, on déploie des **compensating controls** (segmentation, filtrage, surveillance renforcée) et l'on documente formellement une **exception** validée par un responsable.", obj: "4.3" },
    { q: "Quelle différence entre un programme de responsible disclosure et un bug bounty ?", o: ["Le bug bounty est illégal", "Le bug bounty ajoute une récompense financière au signalement coordonné", "La responsible disclosure ne concerne que les employés", "Il n'y a aucune différence"], c: 1,
      e: "La **responsible disclosure** offre un **canal officiel** de signalement coordonné. Le **bug bounty** y ajoute une **récompense financière** proportionnelle à la gravité, ce qui attire davantage de chercheurs.", obj: "4.3" },
    { q: "Quelle source de renseignement sur les menaces est gratuite et publiquement accessible ?", o: ["Les flux propriétaires payants", "L'OSINT", "Le dark web uniquement", "Les rapports internes confidentiels"], c: 1,
      e: "L'**OSINT (Open-Source Intelligence)** repose sur des **sources ouvertes et gratuites**. Les flux **proprietary/third-party** sont payants, et les **information-sharing organizations** (ISAC) sont réservées à leurs membres sectoriels.", obj: "4.3" },
    { q: "Pourquoi un scan de vulnérabilités ne remplace-t-il pas un test d'intrusion ?", o: ["Parce qu'il est plus cher", "Parce qu'il identifie des faiblesses potentielles sans les exploiter ni démontrer l'impact réel", "Parce qu'il ne fonctionne qu'en interne", "Parce qu'il ne détecte que les malwares"], c: 1,
      e: "Le **scan identifie automatiquement des faiblesses potentielles**, souvent avec des faux positifs. Le **pentest les exploite réellement**, démontre l'**impact concret** et met au jour les **chaînes d'attaque** combinant plusieurs failles mineures.", obj: "4.3" }
  ],

  /* ------------------------ 23. Alerting and Monitoring ------------------- */
  23: [
    { q: "Quelle est la fonction qui distingue un SIEM d'un simple serveur de logs centralisé ?", o: ["Il stocke plus de données", "Il corrèle des événements provenant de sources différentes pour révéler un scénario d'attaque", "Il chiffre les journaux", "Il remplace l'antivirus"], c: 1,
      e: "L'**agrégation** centralise les journaux ; c'est la **corrélation** qui fait la valeur du SIEM. Elle **met en relation des événements de sources différentes** pour révéler une attaque invisible si l'on regarde chaque source isolément.", obj: "4.4" },
    { q: "Les analystes reçoivent tant d'alertes qu'ils commencent à en ignorer. Quelle pratique corrige ce problème ?", o: ["Augmenter le nombre d'analystes", "L'alert tuning", "Désactiver le SIEM", "Archiver plus fréquemment"], c: 1,
      e: "L'**alert tuning** ajuste les règles pour **réduire le bruit et les faux positifs**. Sans lui, l'**alert fatigue** s'installe et les équipes finissent par **passer à côté de vraies alertes** noyées dans la masse.", obj: "4.4" },
    { q: "Quelle différence entre un SNMP trap et le polling SNMP ?", o: ["Le trap est envoyé spontanément par l'agent, le polling est une interrogation par le manager", "Le trap est chiffré, le polling non", "Le polling utilise le port 162", "Il n'y a aucune différence"], c: 0,
      e: "Le **trap est émis SPONTANÉMENT par l'agent** vers le manager (port **162**) dès qu'un événement survient. En **polling**, c'est le **manager qui interroge** périodiquement l'agent (port **161**).", obj: "4.4" },
    { q: "Une équipe veut analyser les tendances de trafic réseau sans stocker le contenu des communications. Quelle technologie ?", o: ["Packet capture (PCAP)", "NetFlow", "SIEM", "FIM"], c: 1,
      e: "**NetFlow** enregistre les **métadonnées des flux** (source, destination, volume, durée) sans le contenu : léger et parfait pour l'analyse de tendances. Le **PCAP** capturerait tout le contenu, avec un volume et une sensibilité bien supérieurs.", obj: "4.4" },
    { q: "À quoi sert SCAP ?", o: ["À chiffrer les communications", "À automatiser la vérification de conformité et de vulnérabilités selon des standards", "À gérer les identités", "À sauvegarder les configurations"], c: 1,
      e: "Le **SCAP (Security Content Automation Protocol)** regroupe des standards (**CVE, CVSS, CPE, OVAL, XCCDF**) permettant d'**automatiser la vérification de conformité et de vulnérabilités** de manière interopérable.", obj: "4.4" },
    { q: "Pourquoi la synchronisation NTP est-elle indispensable au bon fonctionnement d'un SIEM ?", o: ["Pour réduire la consommation réseau", "Sans horloges synchronisées, la corrélation chronologique entre sources devient impossible", "Pour chiffrer les journaux", "Pour accélérer l'archivage"], c: 1,
      e: "La corrélation repose sur la **chronologie des événements**. Si les horloges des équipements divergent, il devient **impossible de reconstituer l'ordre réel** des faits et donc le déroulement de l'attaque.", obj: "4.4" },
    { q: "Quelle différence entre supervision agent-based et agentless ?", o: ["L'agent-based ne fonctionne qu'en cloud", "L'agent-based installe un logiciel sur l'hôte et fournit des données plus riches, l'agentless évite l'installation mais offre moins de profondeur", "L'agentless est toujours plus précis", "Il n'y a aucune différence"], c: 1,
      e: "L'approche **agent-based** installe un logiciel sur l'hôte : données **riches et continues**, mais déploiement et maintenance lourds. L'**agentless** évite toute installation, ce qui simplifie le déploiement au prix d'une **visibilité moins profonde**.", obj: "4.4" },
    { q: "Pourquoi archiver les journaux de sécurité sur le long terme ?", o: ["Pour améliorer les performances du SIEM", "Pour satisfaire aux obligations légales de rétention et permettre des investigations rétrospectives", "Pour réduire l'espace disque", "Ce n'est jamais nécessaire"], c: 1,
      e: "L'**archiving** répond aux **obligations réglementaires de rétention** et permet les **investigations rétrospectives**. Une intrusion étant souvent découverte des mois après les faits, sans archives il devient impossible de reconstituer l'attaque.", obj: "4.4" },
    { q: "Que sont les benchmarks CIS et DISA STIG ?", o: ["Des outils de scan réseau", "Des configurations de référence durcies et mesurables", "Des algorithmes de chiffrement", "Des protocoles d'authentification"], c: 1,
      e: "Les **benchmarks** (CIS, DISA STIG) sont des **configurations de référence durcies**, détaillées et **mesurables**. Ils servent de base à l'établissement des secure baselines et à la vérification automatisée de conformité.", obj: "4.4" }
  ],

  /* --------------------------- 24. Incident Response ---------------------- */
  24: [
    { q: "Quel est l'ordre correct des phases de la réponse à incident ?", o: ["Detection, Preparation, Analysis, Recovery, Containment, Eradication, Lessons Learned", "Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons Learned", "Preparation, Containment, Detection, Analysis, Recovery, Eradication, Lessons Learned", "Detection, Analysis, Preparation, Eradication, Containment, Recovery, Lessons Learned"], c: 1,
      e: "L'ordre officiel est **Preparation → Detection → Analysis → Containment → Eradication → Recovery → Lessons Learned**. Retenir que la **préparation précède tout** et que les **leçons apprises closent** le cycle.", obj: "4.8" },
    { q: "Un poste est identifié comme infecté par un ransomware en cours de propagation. Quelle est la PREMIÈRE action à mener ?", o: ["Analyser le malware en détail", "Isoler le poste du réseau", "Restaurer les sauvegardes", "Rédiger le rapport d'incident"], c: 1,
      e: "La question demande la **PREMIÈRE** action : c'est le **containment**, donc **isoler immédiatement** le poste pour stopper la propagation. L'analyse approfondie, l'éradication et la restauration viennent ensuite.", obj: "4.8" },
    { q: "Une équipe recherche activement des traces de compromission non détectées, en partant d'hypothèses et sans qu'aucune alerte n'ait été déclenchée. De quelle activité s'agit-il ?", o: ["Incident response", "Threat hunting", "Vulnerability scanning", "Penetration testing"], c: 1,
      e: "Le **threat hunting** est une recherche **PROACTIVE**, fondée sur des **hypothèses**, d'une compromission déjà présente mais non détectée. Contrairement à la réponse à incident, il **ne part d'aucune alerte**.", obj: "4.8" },
    { q: "Dans quel ordre faut-il collecter les preuves selon l'ordre de volatilité ?", o: ["Disque, RAM, registres, archives", "Registres et cache, RAM, état réseau, processus, disque, journaux distants, archives", "Archives, disque, RAM, registres", "Journaux distants, disque, RAM, cache"], c: 1,
      e: "On collecte **du plus volatil au moins volatil** : **registres/cache → RAM → état réseau → processus → disque → journaux distants → archives**. Les données volatiles disparaissent à l'extinction, il faut donc les saisir en premier.", obj: "4.8" },
    { q: "Pourquoi la chain of custody est-elle critique en investigation numérique ?", o: ["Elle accélère l'analyse", "Toute rupture rend la preuve irrecevable en justice", "Elle chiffre les preuves", "Elle réduit le coût de l'expertise"], c: 1,
      e: "La **chain of custody** documente en continu qui a manipulé la preuve, quand et comment. **Toute rupture ou lacune** permet de contester l'intégrité de la preuve, qui devient alors **irrecevable devant un tribunal**.", obj: "4.8" },
    { q: "Comment réalise-t-on correctement une copie forensique d'un disque ?", o: ["En copiant les fichiers avec l'explorateur Windows", "Une copie bit à bit avec un bloqueur d'écriture, vérifiée par hachage", "En compressant le disque dans une archive ZIP", "En redémarrant la machine sur le disque original"], c: 1,
      e: "Une copie forensique valide est **bit à bit**, réalisée avec un **write blocker** pour ne pas altérer l'original, et **vérifiée par empreinte de hachage** avant et après. On travaille ensuite **uniquement sur la copie**.", obj: "4.8" },
    { q: "Une entreprise reçoit l'ordre de conserver toutes les données liées à un litige, suspendant ses règles de suppression automatique. De quoi s'agit-il ?", o: ["D'un e-discovery", "D'un legal hold", "D'une chain of custody", "D'une attestation"], c: 1,
      e: "Le **legal hold** est l'**obligation juridique de préserver** toutes les données pouvant servir de preuve, ce qui **suspend les politiques normales de rétention et de suppression**. Le non-respect expose à de lourdes sanctions.", obj: "4.8" },
    { q: "Quelle phase de la réponse à incident est la plus souvent négligée en pratique alors qu'elle est systématiquement testée à l'examen ?", o: ["La détection", "Le containment", "Les lessons learned", "La récupération"], c: 2,
      e: "Les **lessons learned** sont souvent sacrifiées une fois la crise passée, alors qu'elles seules permettent d'**améliorer le plan et les contrôles** pour éviter la récidive. CompTIA insiste systématiquement dessus.", obj: "4.8" },
    { q: "Quelle différence entre un tabletop exercise et une simulation ?", o: ["Le tabletop mobilise réellement les systèmes, la simulation non", "Le tabletop est une discussion sur scénario, la simulation une mise en situation réaliste", "Les deux sont identiques", "La simulation ne concerne que le matériel"], c: 1,
      e: "Le **tabletop exercise** est une **discussion autour d'une table**, sans impact sur les systèmes. La **simulation** est une **mise en situation réaliste** (campagne de phishing simulé, exercice de crise) qui teste les réactions effectives.", obj: "4.8" },
    { q: "Quel est l'objectif d'une root cause analysis ?", o: ["Identifier le coupable pour le sanctionner", "Identifier la cause profonde afin d'empêcher la récidive", "Restaurer les données rapidement", "Réduire le coût de l'incident"], c: 1,
      e: "La **root cause analysis** cherche la **cause profonde** et non le symptôme. Sans elle, on traite les effets et l'incident **se reproduit**. Son but est correctif et systémique, pas de désigner un responsable.", obj: "4.8" }
  ],

  /* ----------------------- 25. Investigating an Incident ------------------ */
  25: [
    { q: "Un analyste doit prouver qu'une connexion a bien été établie depuis un poste interne vers une adresse IP externe suspecte. Quelle source consulter en priorité ?", o: ["Les application logs", "Les firewall logs", "Les logs du serveur DHCP", "Les métadonnées des emails"], c: 1,
      e: "Les **firewall logs** enregistrent le trafic **autorisé et bloqué** avec IP source et destination, ports et horodatage. C'est la source de référence pour prouver l'existence d'une connexion réseau sortante.", obj: "4.9" },
    { q: "Pour déterminer si un compte utilisateur a réussi ou échoué à se connecter à un serveur Windows, quelle source consulter ?", o: ["Les IPS logs", "Le Windows Event Log (Security)", "Les NetFlow records", "Les vulnerability scans"], c: 1,
      e: "Les **OS-specific security logs** — le **Windows Event Log (Security)**, ou **auth.log / secure** sous Linux — enregistrent les **tentatives de connexion réussies et échouées** avec le compte concerné.", obj: "4.9" },
    { q: "Un email est chiffré, mais les enquêteurs doivent tout de même établir qui l'a envoyé, quand et depuis quel appareil. Quelle source exploiter ?", o: ["Le contenu du message", "Les métadonnées", "Le certificat racine", "Le fichier hosts"], c: 1,
      e: "Les **métadonnées** (expéditeur, horodatage, appareil, en-têtes de routage, géolocalisation) restent **exploitables même quand le contenu est chiffré**. Elles suffisent souvent à établir un scénario complet.", obj: "4.9" },
    { q: "Quelle source de données est indispensable pour prouver le CONTENU exact de données exfiltrées ?", o: ["NetFlow", "Une capture de paquets (PCAP)", "Les logs DHCP", "Le risk register"], c: 1,
      e: "Seule la **capture de paquets** contient le **contenu réel** des échanges. **NetFlow** indiquerait qu'un transfert volumineux a eu lieu (métadonnées), mais **pas ce qui a été transféré**.", obj: "4.9" },
    { q: "Quelle est la différence entre un dashboard et un automated report ?", o: ["Le dashboard est papier, le rapport numérique", "Le dashboard offre une vue temps réel pour les analystes, le rapport une synthèse périodique pour le pilotage", "Les deux sont identiques", "Le rapport est toujours manuel"], c: 1,
      e: "Le **dashboard** donne une vue **consolidée et en temps réel**, destinée aux analystes opérationnels. L'**automated report** est une **synthèse périodique** orientée pilotage et conformité, à destination du management.", obj: "4.9" },
    { q: "Un analyste ne parvient pas à conclure avec une seule source de logs. Quelle démarche adopter ?", o: ["Abandonner l'investigation", "Corréler plusieurs sources via le SIEM", "Redémarrer les serveurs concernés", "Supprimer les logs ambigus"], c: 1,
      e: "C'est le **recoupement de plusieurs sources** (pare-feu + endpoint + authentification + application) qui permet d'établir le scénario complet. C'est précisément la valeur ajoutée de la **corrélation par un SIEM**.", obj: "4.9" },
    { q: "Quelle source permet d'identifier quelle vulnérabilité a probablement servi de porte d'entrée à l'attaquant ?", o: ["Les vulnerability scans antérieurs à l'intrusion", "Les logs DHCP", "Le registre des risques", "Les métadonnées des documents"], c: 0,
      e: "Les **vulnerability scans** réalisés avant l'intrusion révèlent **quelles faiblesses existaient** sur le système compromis. En les recoupant avec la date de l'attaque, on identifie le vecteur d'entrée le plus probable.", obj: "4.9" }
  ],

  /* --------------------- 26. Automation and Orchestration ----------------- */
  26: [
    { q: "Quelle différence entre automation et orchestration ?", o: ["L'automation coordonne plusieurs outils, l'orchestration une seule tâche", "L'automation automatise une tâche, l'orchestration coordonne plusieurs tâches et outils en un flux complet", "Les deux sont identiques", "L'orchestration ne concerne que le cloud"], c: 1,
      e: "L'**automation automatise UNE tâche** isolée. L'**orchestration coordonne plusieurs tâches et plusieurs outils** en un **flux de bout en bout**. Un SOAR est un outil d'orchestration.", obj: "4.7" },
    { q: "Un mécanisme empêche automatiquement le déploiement d'un stockage cloud configuré en accès public. Comment nomme-t-on cela ?", o: ["Un guard rail", "Un playbook", "Un honeypot", "Un baseline scan"], c: 0,
      e: "Les **guard rails** sont des **garde-fous automatiques** qui **empêchent toute configuration non conforme** d'être déployée. Ils appliquent la politique de sécurité de manière préventive, au moment même du déploiement.", obj: "4.7" },
    { q: "Quel inconvénient majeur de l'automatisation CompTIA insiste-t-il pour que vous reteniez ?", o: ["Elle ralentit les équipes", "Elle crée un point unique de défaillance", "Elle empêche la journalisation", "Elle est toujours plus chère à long terme"], c: 1,
      e: "L'automatisation crée un **single point of failure** : si la plateforme tombe ou est compromise, **tous les processus dépendants s'arrêtent** — ou pire, exécutent des actions malveillantes avec des privilèges élevés.", obj: "4.7" },
    { q: "Pourquoi une automatisation mal conçue est-elle plus dangereuse qu'une erreur manuelle ?", o: ["Parce qu'elle est plus lente à corriger", "Parce qu'elle propage l'erreur à grande échelle et instantanément", "Parce qu'elle ne laisse aucune trace", "Parce qu'elle coûte plus cher"], c: 1,
      e: "Une erreur manuelle reste **isolée** ; une erreur automatisée est **répliquée instantanément sur l'ensemble du parc**. Le rayon d'impact est sans commune mesure, d'où la nécessité de tests et de guard rails.", obj: "4.7" },
    { q: "Que signifie l'expression « workforce multiplier » appliquée à l'automatisation ?", o: ["Il faut recruter davantage d'analystes", "L'équipe existante traite un volume de travail bien supérieur", "Les salaires augmentent automatiquement", "Les effectifs doivent doubler"], c: 1,
      e: "Le **workforce multiplier** signifie que l'automatisation permet à une **équipe de taille constante de traiter beaucoup plus de travail**, en la déchargeant des tâches répétitives au profit de l'analyse à valeur ajoutée.", obj: "4.7" },
    { q: "Quel bénéfice sécurité l'automatisation de l'offboarding apporte-t-elle ?", o: ["Elle réduit le coût des licences", "Elle garantit la révocation immédiate des accès et supprime les comptes orphelins", "Elle améliore la satisfaction des employés partants", "Elle accélère le recrutement"], c: 1,
      e: "L'automatisation de l'**offboarding** garantit que **tous les accès sont révoqués immédiatement et systématiquement** au départ, éliminant les **comptes orphelins** qui constituent une porte d'entrée classique.", obj: "4.7" },
    { q: "Comment sécurise-t-on une API exposée ?", o: ["En la rendant publique sans authentification", "Par authentification, autorisation, rate limiting, validation des entrées et TLS", "En désactivant sa journalisation", "En la limitant au protocole HTTP"], c: 1,
      e: "Une API se sécurise par l'**authentification** forte, l'**autorisation** granulaire, la **limitation de débit (rate limiting)** contre les abus, la **validation des entrées** contre les injections, et le **chiffrement TLS**.", obj: "4.7" },
    { q: "Qu'est-ce que la dette technique dans le contexte de l'automatisation ?", o: ["Le coût financier des licences", "L'accumulation de scripts non documentés et non maintenus qui deviennent impossibles à faire évoluer", "Le temps de formation des équipes", "Le budget alloué au SOC"], c: 1,
      e: "La **dette technique** désigne l'accumulation de **scripts et intégrations non documentés et non maintenus**. Avec le temps, plus personne ne sait comment ils fonctionnent, ce qui rend toute évolution risquée.", obj: "4.7" }
  ],

  /* --------------------------- 27. Security Awareness --------------------- */
  27: [
    { q: "Quel est le véritable objectif d'une campagne de phishing simulé ?", o: ["Sanctionner les employés qui cliquent", "Mesurer et former de façon ciblée, dans une optique pédagogique", "Tester la bande passante du réseau", "Remplacer l'antivirus"], c: 1,
      e: "L'objectif est **pédagogique** : mesurer les taux de clic et de **signalement** pour **cibler la formation**. Utiliser ces campagnes à des fins punitives décourage les signalements, ce qui est contre-productif.", obj: "5.6" },
    { q: "Quel est le cycle correct d'un programme de sensibilisation ?", o: ["Execution, development, monitoring", "Development, execution, reporting and monitoring, révision", "Monitoring, development, execution", "Reporting, execution, development"], c: 1,
      e: "Le cycle est **Development** (conception) → **Execution** (déploiement) → **Reporting and monitoring** → **révision continue**. Le programme doit évoluer en fonction des résultats mesurés.", obj: "5.6" },
    { q: "Des clés USB sont abandonnées sur le parking de l'entreprise. Un employé en branche une par curiosité. Quelle attaque ?", o: ["Watering hole", "USB drop attack", "Evil twin", "Pretexting"], c: 1,
      e: "L'**USB drop attack** exploite la **curiosité humaine** : la clé abandonnée contient une charge malveillante qui s'exécute au branchement. La parade combine formation, **blocage des ports USB** et politiques de supports amovibles.", obj: "5.6" },
    { q: "Quels signaux peuvent trahir un insider threat potentiel ?", o: ["Une bonne performance au travail", "Accès à des données sans lien avec ses fonctions, connexions à des heures inhabituelles, téléchargements massifs", "L'utilisation du VPN d'entreprise", "La participation aux formations de sécurité"], c: 1,
      e: "Les signaux d'alerte sont l'**accès à des données hors périmètre fonctionnel**, des **connexions à des heures inhabituelles**, des **volumes de téléchargement anormaux** et le contournement des contrôles — souvent avant un départ.", obj: "5.6" },
    { q: "Quelle est la différence entre reporting initial et recurring dans un programme de sensibilisation ?", o: ["L'initial établit la mesure de référence, le recurring suit l'évolution dans le temps", "L'initial est facultatif", "Le recurring ne concerne que les nouveaux employés", "Les deux sont identiques"], c: 0,
      e: "Le **reporting initial** établit la **mesure de référence** (le point de départ) ; le **recurring** suit l'**évolution** et démontre si le programme produit réellement des effets.", obj: "5.6" },
    { q: "Quels sont les 3 types de comportements anormaux à reconnaître selon CompTIA ?", o: ["Rapide, lent, moyen", "Risky, unexpected, unintentional", "Interne, externe, hybride", "Technique, managérial, opérationnel"], c: 1,
      e: "CompTIA retient **risky** (risqué en connaissance de cause), **unexpected** (inattendu au regard du rôle) et **unintentional** (involontaire, par méconnaissance). Chacun appelle une réponse différente.", obj: "5.6" },
    { q: "Pourquoi une formation de sensibilisation annuelle unique est-elle insuffisante ?", o: ["Parce qu'elle coûte trop cher", "Parce que les menaces évoluent et que la vigilance décroît avec le temps", "Parce que la loi l'interdit", "Parce qu'elle est trop longue"], c: 1,
      e: "Les **menaces évoluent en permanence** et la **vigilance s'érode naturellement**. Une sensibilisation efficace est **récurrente et variée** : rappels courts, campagnes simulées, communications régulières.", obj: "5.6" },
    { q: "Qu'est-ce que l'OPSEC appliqué au comportement des employés ?", o: ["Le chiffrement des postes de travail", "Ne pas divulguer d'informations exploitables : réseaux sociaux, badges visibles, conversations en public", "La sauvegarde quotidienne des données", "L'installation d'un antivirus"], c: 1,
      e: "L'**OPSEC (Operational Security)** consiste à **ne pas divulguer d'informations exploitables** par un attaquant : publications sur les réseaux sociaux, badge visible hors du site, conversations professionnelles dans les transports.", obj: "5.6" },
    { q: "Pourquoi le télétravail élargit-il la surface d'attaque de l'entreprise ?", o: ["Parce que les employés travaillent moins", "Réseau domestique non maîtrisé, Wi-Fi publics, shoulder surfing et équipements partagés", "Parce que le VPN est vulnérable par nature", "Parce que les logs ne fonctionnent plus"], c: 1,
      e: "Le télétravail introduit des **réseaux domestiques non maîtrisés**, l'usage de **Wi-Fi publics**, le **shoulder surfing** en espace partagé et des **équipements familiaux partagés**. D'où l'exigence de VPN et de postes gérés.", obj: "5.6" }
  ],

  /* ------------------------------ 28. Conclusion -------------------------- */
  28: [
    { q: "Une question demande « What should you do FIRST » face à un serveur compromis en cours d'exfiltration. Quelle logique appliquer ?", o: ["Rédiger le rapport d'incident", "Isoler le système pour stopper la propagation et l'exfiltration", "Lancer une analyse forensique complète", "Prévenir la presse"], c: 1,
      e: "Le mot **FIRST** demande la **première action chronologique**. En réponse à incident, c'est le **containment** : on stoppe l'hémorragie d'abord, on analyse ensuite. Plusieurs réponses sont correctes, mais une seule est la première.", obj: "Stratégie d'examen" },
    { q: "Quels éléments est-il judicieux d'écrire lors du brain dump en début d'examen ?", o: ["Les noms des fournisseurs de sécurité", "Les formules SLE/ALE/ARO, les ports, les 7 phases de l'IR et les modèles de contrôle d'accès", "Le règlement de l'examen", "Les coordonnées du centre d'examen"], c: 1,
      e: "Le **brain dump** doit contenir ce qui est **volumineux, précis et sensible au stress** : **formules de risque**, **ports**, **7 phases de la réponse à incident**, **modèles de contrôle d'accès** et ordre de volatilité.", obj: "Stratégie d'examen" },
    { q: "Une question propose deux réponses techniquement correctes, mais précise « MOST cost-effective ». Comment trancher ?", o: ["Choisir la solution techniquement la plus robuste", "Choisir la solution qui atteint l'objectif au moindre coût", "Choisir la solution la plus rapide à déployer", "Choisir au hasard"], c: 1,
      e: "Les **mots-clés discriminants** (MOST cost-effective, BEST, FIRST, MOST likely) désignent **laquelle des bonnes réponses est attendue**. Ici, il faut la solution **atteignant l'objectif au moindre coût**, même si une autre est techniquement supérieure.", obj: "Stratégie d'examen" },
    { q: "Vous bloquez depuis 3 minutes sur une question difficile. Que faire ?", o: ["Continuer jusqu'à trouver la réponse", "La marquer, choisir une réponse plausible et avancer", "La laisser vide et passer", "Recommencer l'examen"], c: 1,
      e: "Avec **environ une minute par question**, s'attarder ruine la gestion du temps. Il faut **cocher une réponse plausible** (aucune pénalité), **marquer la question** et y revenir si le temps le permet.", obj: "Stratégie d'examen" },
    { q: "Votre expérience professionnelle contredit la réponse « du manuel ». Que privilégier à l'examen ?", o: ["Votre expérience terrain, plus réaliste", "La bonne pratique CompTIA telle qu'enseignée", "La réponse la plus longue", "La première réponse de la liste"], c: 1,
      e: "L'examen évalue la **connaissance des bonnes pratiques CompTIA**, pas les compromis pratiqués sur le terrain. Il faut donc systématiquement répondre **« par le manuel »**, même si la réalité de votre entreprise diffère.", obj: "Stratégie d'examen" },
    { q: "Il vous reste 10 minutes et 3 PBQ non traitées. Quelle stratégie adopter ?", o: ["Les laisser vides pour relire les QCM", "Y répondre partiellement, car les PBQ accordent souvent des points partiels", "En traiter une seule parfaitement et laisser les autres vides", "Signaler un problème technique"], c: 1,
      e: "Les PBQ accordent fréquemment des **points partiels**. Il vaut donc mieux **répondre partiellement aux trois** que d'en parfaire une seule en abandonnant les autres, et il ne faut jamais laisser une PBQ totalement vide.", obj: "Stratégie d'examen" }
  ]

  };
})(window.App = window.App || {});
